-- Pins and their verdict on coleam00/ai-software-factory, through parsePin, pinnedArchonSha and parseVerdict.
INSERT INTO mc.pins (sha, archon_sha, reason, hypothesis, measure, committed_at) VALUES ('8e3e1cefaf1e1b7955789d6a43a81b6c2dbd7082', 'abd85896e7971c9ac5199ed7e87973f27130250f', 'holdouts fenced in the repository; the complex route runs dev''s ship-block', 'complex laps finish faster and are sent back less.', 'complex-route lap-hours per merge and send-backs per merge, over at least 10 complex laps.', '2026-09-30T18:00:00Z');
INSERT INTO mc.pins (sha, archon_sha, reason, hypothesis, measure, committed_at) VALUES ('5ffd60c6c6e591487f2fbb5ec67ccc8fc55ca915', '2b7c4e9a1f0d3c5b6a7e8f9d0c1b2a3f4e5d6c7b', 'the loop drops the briefs step and tallies every lap', NULL, 'lap-hours per merge, lower, over at least 12 laps.', '2026-10-09T18:00:00Z');
INSERT INTO mc.pins (sha, archon_sha, reason, hypothesis, measure, committed_at) VALUES ('58c5f774e1bbe57c80c85ee91df8d44075664232', 'a8551bfe8a7f6e5d4c3b2a1f0e9d8c7b6a5f4e3d', NULL, NULL, NULL, '2026-10-19T18:00:00Z');
INSERT INTO mc.verdicts (sha, pin, verdict, sentence, committed_at) VALUES ('5833269587f5a3cb378a243bed094467aa71801e', '8e3e1cef', 'helped', 'complex laps took 1.4 lap-hours per merge against 2.6, over 12 laps.', '2026-10-09T17:00:00Z');

-- DECISIONS.md on coleam00/ai-software-factory, through parseDecisions.
INSERT INTO mc.decisions (date, title, decision, why, replaces, version) VALUES ('2026-09-30', 'Fence the holdouts inside the repository', 'Holdout scenarios live in the repository behind a fence only the holdout verifier passes.', 'A builder that can read the scenarios learns to pass them instead of building the product.', 'holdout scenarios kept outside the repository.', '8e3e1cef');
INSERT INTO mc.decisions (date, title, decision, why, replaces, version) VALUES ('2026-10-09', 'Drop the briefs step from the loop', 'check-app reads the holdout verifier''s instructions itself; the step that copied them goes.', 'The copy never changed a check, and every lap waited for it.', 'the briefs step.', '5ffd60c6');
INSERT INTO mc.decisions (date, title, decision, why, replaces, version) VALUES ('2026-10-15', 'Run three laps at once', 'The schedule starts a lap while two are running, never a fourth.', 'After the first items most work depends only on the seed, not on each other.', 'one lap at a time.', 'none');
INSERT INTO mc.decisions (date, title, decision, why, replaces, version) VALUES ('2026-10-19', 'Follow dev''s pack', 'The factory runs the workflow pack dev ships, with no local changes.', 'Local changes drifted from dev and each one had to be merged again.', 'a locally edited pack.', 'a8551bfe');

