-- Attention items: two runs paused on a `wait: attention` node, projected by the trigger.
INSERT INTO remote_agent_workflow_runs (id, workflow_name, codebase_id, status, user_message, metadata, started_at, completed_at, last_activity_at) VALUES ('5eed0006-0000-4000-8000-000000000001', 'archon-build-queue', '5eed0000-0000-4000-8000-000000000000', 'paused', 'Work the queue', '{"wait":{"owner":"node","nodeId":"ask","kind":"attention","pauseId":"seed-build-ask","revision":1,"form":"select","options":[{"id":"split","label":"Split the issue in two"},{"id":"build","label":"Build it as written"},{"id":"other","label":"Something else"}],"labels":{"build":"scope"},"waitingSince":"2026-10-24T10:20:00.000Z","message":"**Build queue, issue 15: scope decision**\n\n**What it is.** Issue 15 asks for the lanes panel and the one-lap page in one change, and the two touch different screens.\n\n**Why it matters.** A change that spans both screens is hard to review and holds the queue behind it.\n\n**Recommendation: `split`** (high confidence). Two small changes land sooner than one large one.\nEvidence: the two screens share no component.\nWhat would change it: a shared change that must land with both.\n\n**Choices.**\n- `split` (Split the issue in two): Two issues, one per screen, each reviewed alone.\n- `build` (Build it as written): One change for both screens, reviewed together.\n- `other` (Something else): Say what to do instead.\n\n**If nobody answers.** The queue stays on this issue and takes the next ready one.\n\n**Evidence links.**\n- https://github.com/coleam00/factory-mission-control/issues/15"}}'::jsonb, '2026-10-24T10:20:00.000Z', NULL, '2026-10-24T10:20:00.000Z');
INSERT INTO remote_agent_workflow_runs (id, workflow_name, codebase_id, status, user_message, metadata, started_at, completed_at, last_activity_at) VALUES ('5eed0006-0000-4000-8000-000000000002', 'archon-merge-queue', '5eed0000-0000-4000-8000-000000000000', 'paused', 'Work the queue', '{"wait":{"owner":"node","nodeId":"ask","kind":"attention","pauseId":"seed-merge-ask","revision":1,"form":"select","options":[{"id":"merge","label":"Merge it now","does":"Merge the pull request into the default branch.","value":{"choice":"merge"}},{"id":"hold","label":"Hold it for the next lap","does":"Leave it open and decide again next lap.","value":{"choice":"hold"}},{"id":"other","label":"Something else","does":"Say what to do instead.","value":{"choice":"other"}}],"recommendation":{"option":"merge","why":"Nothing in it waits on another change.","confidence":"medium"},"labels":{"merge":"pr"},"waitingSince":"2026-10-24T11:35:00.000Z","message":"**Merge queue, PR 16: merge decision**\n\n**What it is.** Pull request 16 has every check green and no open review finding.\n\n**Why it matters.** It is the last change before the version is pinned.\n\n**Evidence.** The checks are green and the review has no open finding. A failing check on the base branch would change it.\n\n**If nobody answers.** The queue leaves it open and moves to the next pull request.\n\n**Evidence links.**\n- https://github.com/coleam00/factory-mission-control/pull/16"}}'::jsonb, '2026-10-24T11:35:00.000Z', NULL, '2026-10-24T11:35:00.000Z');

