INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/review/docs', 'rounds/review', 18, 'docs', 'command', NULL, 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.docs == true || $scope.output.head_matches == true && $mode.output.docs == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-docs', 'review/commands/review-docs.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/review/review-complete', 'rounds/review', 19, 'review-complete', 'bash', 'all_done lets this barrier settle after unselected lenses, or a lens whose
retries were exhausted. The deciding
agent can then tolerate specialist failures without also tolerating a failed
mode/scope preflight: synthesize separately requires both to have succeeded.', NULL, '$scope.output.head_matches == true', ARRAY['scope', 'route', 'seams', 'code', 'tests', 'errors', 'docs']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'true', NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/review/synthesize', 'rounds/review', 20, 'synthesize', 'command', 'A failed specialist (a provider stream dying mid-review, say) must not kill
the review: synthesize detects the missing completion for a selected lens and
forces ready:false naming the gap, so degradation is disclosed, never silent,
and the next round is the retry. `ready` is a real boolean — the load-bearing field a composing
loop terminates on. Every round receives this round''s lens files; a
continuation also receives the complete prior report and correction delta.

The deciding agent and the lenses start fresh and carry earlier rounds through
the prior report, not a resumed session: a loop body cannot resume a session
from its own earlier iteration, and session resume is not portable across the
bundle''s supported providers (Claude Code, Codex, and Pi).

Adversarial per-finding verification happens inside this node''s prompt. A
separate verify stage between the lenses and this node is now expressible and
would not change either side''s contract — the findings files are the declared
boundary — but nothing has measured it as better than the in-prompt pass, so
it stays here until something does.', 'medium', '$scope.output.head_matches == true', ARRAY['policy', 'mode', 'scope', 'review-complete']::text[], NULL, NULL, NULL, NULL, 'review-synthesize', 'review/commands/review-synthesize.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/review/publish', 'rounds/review', 21, 'publish', 'script', 'The reviewer judges and writes the report; this node owns the one public
write, so every round edits the same marked comment instead of appending
another, through whichever forge source the run selected. The verdict passes
through unchanged: publication is not what makes a review true.', NULL, '$scope.output.head_matches == true', ARRAY['synthesize']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'publish-review', 'review/scripts/publish-review.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/review/result', 'rounds/review', 22, 'result', 'script', 'Standalone runs show the first completed sink, so the verdict precedes cleanup.', NULL, NULL, ARRAY['scope', 'publish']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, NULL, NULL, 'const verdict = JSON.parse(process.env.INPUTS_VERDICT);
const report = JSON.parse(process.env.INPUTS_SCOPE_REPORT);
console.log(JSON.stringify(JSON.parse(process.env.INPUTS_HEAD_MATCHES) ? verdict : {
  ready: false, action: "ask",
  findings_summary: require("node:fs").readFileSync(require("node:path").join(process.env.ARTIFACTS_DIR, report.path), "utf8"),
  report, discoveries: [], contract_left: ["PR head mismatch prevented contract review."]
}));
', NULL, 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/review/prune-scratch', 'rounds/review', 23, 'prune-scratch', 'script', 'Reviewers'' scratch worktrees are removed by the workflow once every lens and
the deciding agent have settled, whether they succeeded or failed.', NULL, NULL, ARRAY['synthesize']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, 'prune-scratch', 'review/scripts/prune-scratch.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/simplify', 'rounds', 24, 'simplify', 'include', 'After a review passes, before CI. Once per run: a later round finds the
earlier shape.md and declares no findings (see simplify.md).', NULL, '$review.output.ready == true', ARRAY['review']::text[], NULL, 'archon-simplify', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/simplify/simplify', 'rounds/simplify', 25, 'simplify', 'command', NULL, 'medium', NULL, '{}'::text[], NULL, NULL, NULL, NULL, 'simplify', 'simplify/commands/simplify.md', NULL, NULL, NULL, NULL, NULL, 'archon-simplify', 'simplify/archon-simplify.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/simplify/prune-scratch', 'rounds/simplify', 26, 'prune-scratch', 'script', 'Scratch worktrees the lens tried mutations in are removed by the workflow,
whether the lens succeeded or failed.', NULL, NULL, ARRAY['simplify']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, 'prune-scratch', 'simplify/scripts/prune-scratch.ts', 'bun', NULL, NULL, 'archon-simplify', 'simplify/archon-simplify.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/reshape', 'rounds', 27, 'reshape', 'include', 'Implement a change and keep working until it is complete and the focused checks
on what it changed pass. Commits as it goes; opens no PR. The input is anything intent-shaped:
a plan (path or inline), review findings, a CI failure to fix, or a plain
description of what to build.

Use when: the work is already decided and needs building — "implement this plan",
"apply these review findings", "build what this describes", "fix this CI failure".
NOT for: deciding what to build, reviewing changes, or opening a PR.
', NULL, '$simplify.output.findings == true', ARRAY['simplify']::text[], NULL, 'archon-implement', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/reshape/implement', 'rounds/reshape', 28, 'implement', 'loop', 'Run success ≠ green. The loop completes on `done`, which deliberately includes
a definitive blocked decline (green: false) — so a completed run''s status never
certifies the work. Consumers read $implement.output.green; compositions gate on
it deterministically before spending or shipping (deliver''s pr step does), and the
workflow''s outcome_field records it as the run''s authored outcome.
Each turn is a fresh session: work that continues past a seam is carried by its
commits and implementation.md, never by a conversation that grows with the work.', 'large', NULL, '{}'::text[], NULL, NULL, NULL, NULL, 'implement', 'implement/commands/implement.md', NULL, NULL, NULL, NULL, NULL, 'archon-implement', 'implement/archon-implement.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/rereview', 'rounds', 29, 'rereview', 'include', 'Reshape commits after review passed, so its delta is reviewed before CI, by
the light review a CI fix gets: the code lens alone, on the delta.', NULL, NULL, ARRAY['reshape']::text[], NULL, 'archon-review-block', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/rereview/policy', 'rounds/rereview', 30, 'policy', 'script', 'The directory of the pack''s default policy documents in this run''s captured
source, the same in a source checkout and a binary install. Synthesis names the
policy file it needs and reads the default, then the project''s own on top.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'policy', 'review/scripts/policy.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/rereview/mode', 'rounds/rereview', 31, 'mode', 'script', 'After scope accepts the checkout, fixes what this round reviews: whether it
continues a previous round, the commit under review (the checkout''s HEAD as
the engine observed it), and, on a continuation, the previous round''s
reviewed commit, which the head must descend from. A caller''s pull-request
record names the PR, never the commit: its head revision goes stale with
every push after the PR opens. publish refuses a report about any other
commit. The node also turns the input into the routable fact the lenses gate
on: an include''s inputs are substituted as text at load time and cannot be
compared in a `when:`. For the same reason it carries the part assignment, so
synthesis reads a value certified against its schema, not raw text.', NULL, '$scope.output.head_matches == true', ARRAY['scope']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'review-round', 'review/scripts/review-round.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/rereview/review-dir', 'rounds/rereview', 32, 'review-dir', 'bash', 'Every review node writes under review/, and a fresh run''s artifacts directory
has none. Agents told to create it have skipped that step, so the declared
scope.md pointer failed and took the whole delivery run down with it.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'mkdir -p "$ARTIFACTS_DIR/review"', NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/rereview/scope', 'rounds/rereview', 33, 'scope', 'command', NULL, 'medium', NULL, ARRAY['review-dir']::text[], NULL, NULL, NULL, NULL, 'review-scope', 'review/commands/review-scope.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/rereview/route', 'rounds/rereview', 34, 'route', 'command', 'After scope checks the head, a small model reads the diff
summary and the work order and answers, with seams on by default. Every round
but a light one routes; on a continuation route adds to the code lens every lens
whose finding the previous report leaves open or whose area the delta touches.', 'small', '$scope.output.head_matches == true && $mode.output.light == false', ARRAY['mode', 'scope']::text[], NULL, NULL, NULL, NULL, 'route-review', 'review/commands/route-review.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/rereview/seams', 'rounds/rereview', 35, 'seams', 'command', '── Lenses ────────────────────────────────────────────────────────
Every reviewer is read-only by the engine''s check, not only by its prompt:
lenses run in parallel in one checkout, so a reviewer that edits it can
mislead the others. `&&` binds tighter than `||` and short-circuits, so a
light round, which skips the route node, never reads it.', 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.seams == true || $scope.output.head_matches == true && $mode.output.seams == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-seams', 'review/commands/review-seams.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/rereview/code', 'rounds/rereview', 36, 'code', 'command', NULL, 'large', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.code == true || $scope.output.head_matches == true && $mode.output.code == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-code', 'review/commands/review-code.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/rereview/tests', 'rounds/rereview', 37, 'tests', 'command', NULL, 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.tests == true || $scope.output.head_matches == true && $mode.output.tests == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-tests', 'review/commands/review-tests.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
