INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/rereview/review-complete', 'rounds/rereview', 40, 'review-complete', 'bash', 'all_done lets this barrier settle after unselected lenses, or a lens whose
retries were exhausted. The deciding
agent can then tolerate specialist failures without also tolerating a failed
mode/scope preflight: synthesize separately requires both to have succeeded.', NULL, '$scope.output.head_matches == true', ARRAY['scope', 'route', 'seams', 'code', 'tests', 'errors', 'docs']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'true', NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/rereview/synthesize', 'rounds/rereview', 41, 'synthesize', 'command', 'A failed specialist (a provider stream dying mid-review, say) must not kill
the review: synthesize detects the missing completion for a selected lens and
forces ready:false naming the gap, so degradation is disclosed, never silent,
and the next round is the retry. `ready` is a real boolean — the load-bearing field a composing
loop terminates on. Every round receives this round''s lens files; a
continuation also receives the complete prior report and correction delta.

The deciding agent and the lenses start fresh and carry earlier rounds through
the prior report, not a resumed session: a loop body cannot resume a session
from its own earlier iteration, and session resume is not portable across the
bundle''s supported providers (Claude Code, Codex, and Pi).

Adversarial per-finding verification happens inside this node''s prompt. A
separate verify stage between the lenses and this node is now expressible and
would not change either side''s contract — the findings files are the declared
boundary — but nothing has measured it as better than the in-prompt pass, so
it stays here until something does.', 'medium', '$scope.output.head_matches == true', ARRAY['policy', 'mode', 'scope', 'review-complete']::text[], NULL, NULL, NULL, NULL, 'review-synthesize', 'review/commands/review-synthesize.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/rereview/publish', 'rounds/rereview', 42, 'publish', 'script', 'The reviewer judges and writes the report; this node owns the one public
write, so every round edits the same marked comment instead of appending
another, through whichever forge source the run selected. The verdict passes
through unchanged: publication is not what makes a review true.', NULL, '$scope.output.head_matches == true', ARRAY['synthesize']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'publish-review', 'review/scripts/publish-review.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/rereview/result', 'rounds/rereview', 43, 'result', 'script', 'Standalone runs show the first completed sink, so the verdict precedes cleanup.', NULL, NULL, ARRAY['scope', 'publish']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, NULL, NULL, 'const verdict = JSON.parse(process.env.INPUTS_VERDICT);
const report = JSON.parse(process.env.INPUTS_SCOPE_REPORT);
console.log(JSON.stringify(JSON.parse(process.env.INPUTS_HEAD_MATCHES) ? verdict : {
  ready: false, action: "ask",
  findings_summary: require("node:fs").readFileSync(require("node:path").join(process.env.ARTIFACTS_DIR, report.path), "utf8"),
  report, discoveries: [], contract_left: ["PR head mismatch prevented contract review."]
}));
', NULL, 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'rounds/rereview/prune-scratch', 'rounds/rereview', 44, 'prune-scratch', 'script', 'Reviewers'' scratch worktrees are removed by the workflow once every lens and
