INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-deliver-block', 'update-pr-body', NULL, 49, 'update-pr-body', 'command', 'Corrections and the base merge can falsify claims the description made when the
draft opened, and an implementer can pass red the description must disclose. One
agent reads the live description and the final diff, and edits only what is no
longer true. It also links the issue by the latest review''s coverage: closing
only when nothing is left. It runs once the rounds have ended, never per round;
content a round prepared for the description is that round''s pr step''s write.', 'medium', '$rounds.output.pr_url != ''''', ARRAY['rounds']::text[], NULL, NULL, NULL, NULL, 'update-pr-body', 'deliver/commands/update-pr-body.md', NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
