INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-plan-block', 'policy', NULL, 0, 'policy', 'script', 'The directory of the pack''s default policy documents in this run''s captured
source, the same in a source checkout and a binary install. The prompt names the
policy file it needs and reads the default, then the project''s own on top.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'policy', 'plan/scripts/policy.ts', 'bun', NULL, NULL, 'archon-plan-block', 'plan/archon-plan-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-plan-block', 'plan', NULL, 1, 'plan', 'command', 'Open questions are a valid outcome, not a failure: the calls only a person can
make, named, beat a plan built on guesses. Whether the plan is ready is the
planner''s judgment; consumers gate on $plan.output.ready and relay
$plan.output.open_questions either way. A schema cannot tie the two without a
root union, which the providers'' structured output rejects, so the prompt
holds the rule: not ready always names at least one question.', 'large', NULL, ARRAY['policy']::text[], NULL, NULL, NULL, NULL, 'plan', 'plan/commands/plan.md', NULL, NULL, NULL, NULL, NULL, 'archon-plan-block', 'plan/archon-plan-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-pr', 'forge', NULL, 0, 'forge', 'script', 'Refuses the run before the agent spends when the selected forge source cannot
act: no plugin for the host, no usable credential, or an unauthenticated gh.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'forge-check', 'pr/scripts/forge-check.ts', 'bun', NULL, NULL, 'archon-pr', 'pr/archon-pr.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-pr', 'prepare', NULL, 1, 'prepare', 'command', 'The agent judges: which repository the work is proposed to, the base, whether
the run continues an existing pull request, and what the title and body say.
It performs no push and no forge write.', 'medium', NULL, ARRAY['forge']::text[], NULL, NULL, NULL, NULL, 'pr', 'pr/commands/pr.md', NULL, NULL, NULL, NULL, NULL, 'archon-pr', 'pr/archon-pr.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-pr', 'publish', NULL, 2, 'publish', 'script', 'The durable ownership record for every later public action in delivery and
inbound forge event. It pushes the branch, then opens the pull request, or
reuses the one this work already has; consumers use this qualified identity,
never gh''s ambient branch lookup.', NULL, NULL, ARRAY['prepare']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'publish-pr', 'pr/scripts/publish-pr.ts', 'bun', NULL, NULL, 'archon-pr', 'pr/archon-pr.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-regress', 'before', NULL, 0, 'before', 'script', NULL, NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'identity', 'regress/scripts/identity.py', 'uv', NULL, NULL, 'archon-regress', 'regress/archon-regress.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-regress', 'validate', NULL, 1, 'validate', 'include', 'Discover and run the project''s own checks — types, lint, tests, build,
whatever the repository itself defines — and report a structured verdict.
Judges nothing and fixes nothing: it runs what the project declares and
tells the truth about the result.

Use when: the current state of the checkout needs a validation verdict —
"run the checks", "is this green", "validate this".
NOT for: fixing failures (implement) or reviewing code (review).
', NULL, NULL, ARRAY['before']::text[], NULL, 'archon-validate', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-regress', 'regress/archon-regress.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-regress', 'validate/mode', 'validate', 2, 'mode', 'script', NULL, NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'mode', 'validate/scripts/mode.ts', 'bun', NULL, NULL, 'archon-validate', 'validate/archon-validate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-regress', 'validate/compare', 'validate', 3, 'compare', 'script', NULL, NULL, '$mode.output.comparison == true', ARRAY['mode']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'compare', 'validate/scripts/compare.ts', 'bun', NULL, NULL, 'archon-validate', 'validate/archon-validate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-regress', 'validate/applicability', 'validate', 4, 'applicability', 'script', 'A run that reaches validation again after a pause (an approval, a CI wait, an
operator''s resume) reuses the verdict it already reached when nothing that
verdict measured has changed: the tracked tree, scope, context, this validator''s
own sources and the recorded report. Decided on every pass, never cached, and
only a green verdict with performed checks is ever reused. The rules are in
.shared/validation-evidence.ts.', NULL, '$mode.output.comparison == false', ARRAY['mode']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'applicability', 'validate/scripts/applicability.ts', 'bun', NULL, NULL, 'archon-validate', 'validate/archon-validate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-regress', 'validate/discover', 'validate', 5, 'discover', 'command', 'Ordinary validation is three nodes. Finding the gate is judgement, so an agent
does it. Running the gate is computation, so a script does it: an agent''s
shell tool has a per-call time limit that a project''s gate can outlast, and a
script node runs for as long as its own `timeout:` allows. Judging why a
check failed is judgement again, so only a red run reaches an agent.', 'medium', '$applicability.output.reuse == false', ARRAY['applicability']::text[], NULL, NULL, NULL, NULL, 'discover-checks', 'validate/commands/discover-checks.md', NULL, NULL, NULL, NULL, NULL, 'archon-validate', 'validate/archon-validate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-regress', 'validate/run', 'validate', 6, 'run', 'script', 'Runs the declared checks and records every exit status in
`$ARTIFACTS_DIR/validation.md`. Green and "didn''t finish" are read from those
exit statuses, never from a clock. The timeout is sized for a slow gate on a
loaded machine. When it stops the gate anyway, the node is skipped and
`result` reports `incomplete`.', NULL, NULL, ARRAY['discover']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'run-checks', 'validate/scripts/run-checks.ts', 'bun', NULL, NULL, 'archon-validate', 'validate/archon-validate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-regress', 'validate/classify', 'validate', 7, 'classify', 'command', NULL, 'medium', '$run.output.status == ''red''', ARRAY['run']::text[], NULL, NULL, NULL, NULL, 'classify-red', 'validate/commands/classify-red.md', NULL, NULL, NULL, NULL, NULL, 'archon-validate', 'validate/archon-validate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-regress', 'validate/result', 'validate', 8, 'result', 'script', 'The one verdict. A fresh ordinary verdict is recorded here as evidence, with
the report it came with; a reuse decision selects the recorded one instead.', NULL, NULL, ARRAY['compare', 'applicability', 'discover', 'run', 'classify']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, NULL, NULL, 'result', 'validate/scripts/result.ts', 'bun', NULL, NULL, 'archon-validate', 'validate/archon-validate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-regress', 'checked', NULL, 9, 'checked', 'script', NULL, NULL, NULL, ARRAY['before', 'validate']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'identity', 'regress/scripts/identity.py', 'uv', NULL, NULL, 'archon-regress', 'regress/archon-regress.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-regress', 'route', NULL, 10, 'route', 'script', NULL, NULL, NULL, ARRAY['checked', 'validate']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'route', 'regress/scripts/route.py', 'uv', NULL, NULL, 'archon-regress', 'regress/archon-regress.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-regress', 'investigate', NULL, 11, 'investigate', 'include', 'Establish the proven causal chain for a bug, unexplained behavior, or open
question — to the root cause whose fix prevents the symptom, never the first
plausible explanation — and write an evidence-backed report a fixer or
planner can act on without repeating the work. Advisory: it reads,
reproduces, and reports — the repository is left exactly as it was found.

Use when: the cause is not yet known — "investigate this issue", "why does
this fail", "root-cause this before we fix it".
NOT for: deciding how to build the fix (plan), or building it (implement).
', NULL, '$route.output.investigate == true', ARRAY['route']::text[], NULL, 'archon-investigate', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-regress', 'regress/archon-regress.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-regress', 'investigate/investigate', 'investigate', 12, 'investigate', 'command', 'Inconclusive is a valid outcome, not a failure: the gaps named honestly beat a
confident guess. Consumers gate on the verdict before building on the chain.', 'medium', NULL, '{}'::text[], NULL, NULL, NULL, NULL, 'investigate', 'investigate/commands/investigate.md', NULL, NULL, NULL, NULL, NULL, 'archon-investigate', 'investigate/archon-investigate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-regress', 'investigate/verdict', 'investigate', 13, 'verdict', 'script', NULL, NULL, NULL, ARRAY['investigate']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'verdict', 'investigate/scripts/verdict.ts', 'bun', NULL, NULL, 'archon-investigate', 'investigate/archon-investigate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-regress', 'after', NULL, 14, 'after', 'script', 'Record the final identity even if a producer fails. Failed producers still
fail the run; their missing output cannot become a healthy diagnosis.', NULL, NULL, ARRAY['before', 'validate', 'checked', 'route', 'investigate']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, 'identity', 'regress/scripts/identity.py', 'uv', NULL, NULL, 'archon-regress', 'regress/archon-regress.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-regress', 'report', NULL, 15, 'report', 'script', NULL, NULL, NULL, ARRAY['before', 'validate', 'checked', 'route', 'investigate', 'after']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, NULL, NULL, 'report', 'regress/scripts/report.py', 'uv', NULL, NULL, 'archon-regress', 'regress/archon-regress.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-review-block', 'policy', NULL, 0, 'policy', 'script', 'The directory of the pack''s default policy documents in this run''s captured
source, the same in a source checkout and a binary install. Synthesis names the
policy file it needs and reads the default, then the project''s own on top.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'policy', 'review/scripts/policy.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-review-block', 'mode', NULL, 1, 'mode', 'script', 'After scope accepts the checkout, fixes what this round reviews: whether it
continues a previous round, the commit under review (the checkout''s HEAD as
the engine observed it), and, on a continuation, the previous round''s
reviewed commit, which the head must descend from. A caller''s pull-request
record names the PR, never the commit: its head revision goes stale with
every push after the PR opens. publish refuses a report about any other
commit. The node also turns the input into the routable fact the lenses gate
on: an include''s inputs are substituted as text at load time and cannot be
compared in a `when:`. For the same reason it carries the part assignment, so
synthesis reads a value certified against its schema, not raw text.', NULL, '$scope.output.head_matches == true', ARRAY['scope']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'review-round', 'review/scripts/review-round.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-review-block', 'review-dir', NULL, 2, 'review-dir', 'bash', 'Every review node writes under review/, and a fresh run''s artifacts directory
has none. Agents told to create it have skipped that step, so the declared
scope.md pointer failed and took the whole delivery run down with it.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'mkdir -p "$ARTIFACTS_DIR/review"', NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-review-block', 'scope', NULL, 3, 'scope', 'command', NULL, 'medium', NULL, ARRAY['review-dir']::text[], NULL, NULL, NULL, NULL, 'review-scope', 'review/commands/review-scope.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-review-block', 'route', NULL, 4, 'route', 'command', 'After scope checks the head, a small model reads the diff
summary and the work order and answers, with seams on by default. Every round
but a light one routes; on a continuation route adds to the code lens every lens
whose finding the previous report leaves open or whose area the delta touches.', 'small', '$scope.output.head_matches == true && $mode.output.light == false', ARRAY['mode', 'scope']::text[], NULL, NULL, NULL, NULL, 'route-review', 'review/commands/route-review.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-review-block', 'seams', NULL, 5, 'seams', 'command', '── Lenses ────────────────────────────────────────────────────────
Every reviewer is read-only by the engine''s check, not only by its prompt:
lenses run in parallel in one checkout, so a reviewer that edits it can
mislead the others. `&&` binds tighter than `||` and short-circuits, so a
light round, which skips the route node, never reads it.', 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.seams == true || $scope.output.head_matches == true && $mode.output.seams == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-seams', 'review/commands/review-seams.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-review-block', 'code', NULL, 6, 'code', 'command', NULL, 'large', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.code == true || $scope.output.head_matches == true && $mode.output.code == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-code', 'review/commands/review-code.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-review-block', 'tests', NULL, 7, 'tests', 'command', NULL, 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.tests == true || $scope.output.head_matches == true && $mode.output.tests == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-tests', 'review/commands/review-tests.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-review-block', 'errors', NULL, 8, 'errors', 'command', NULL, 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.errors == true || $scope.output.head_matches == true && $mode.output.errors == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-errors', 'review/commands/review-errors.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-review-block', 'docs', NULL, 9, 'docs', 'command', NULL, 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.docs == true || $scope.output.head_matches == true && $mode.output.docs == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-docs', 'review/commands/review-docs.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-review-block', 'review-complete', NULL, 10, 'review-complete', 'bash', 'all_done lets this barrier settle after unselected lenses, or a lens whose
retries were exhausted. The deciding
agent can then tolerate specialist failures without also tolerating a failed
mode/scope preflight: synthesize separately requires both to have succeeded.', NULL, '$scope.output.head_matches == true', ARRAY['scope', 'route', 'seams', 'code', 'tests', 'errors', 'docs']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'true', NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-review-block', 'synthesize', NULL, 11, 'synthesize', 'command', 'A failed specialist (a provider stream dying mid-review, say) must not kill
the review: synthesize detects the missing completion for a selected lens and
forces ready:false naming the gap, so degradation is disclosed, never silent,
and the next round is the retry. `ready` is a real boolean — the load-bearing field a composing
loop terminates on. Every round receives this round''s lens files; a
continuation also receives the complete prior report and correction delta.

The deciding agent and the lenses start fresh and carry earlier rounds through
the prior report, not a resumed session: a loop body cannot resume a session
from its own earlier iteration, and session resume is not portable across the
bundle''s supported providers (Claude Code, Codex, and Pi).

Adversarial per-finding verification happens inside this node''s prompt. A
separate verify stage between the lenses and this node is now expressible and
would not change either side''s contract — the findings files are the declared
boundary — but nothing has measured it as better than the in-prompt pass, so
it stays here until something does.', 'medium', '$scope.output.head_matches == true', ARRAY['policy', 'mode', 'scope', 'review-complete']::text[], NULL, NULL, NULL, NULL, 'review-synthesize', 'review/commands/review-synthesize.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-review-block', 'publish', NULL, 12, 'publish', 'script', 'The reviewer judges and writes the report; this node owns the one public
write, so every round edits the same marked comment instead of appending
another, through whichever forge source the run selected. The verdict passes
through unchanged: publication is not what makes a review true.', NULL, '$scope.output.head_matches == true', ARRAY['synthesize']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'publish-review', 'review/scripts/publish-review.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-review-block', 'result', NULL, 13, 'result', 'script', 'Standalone runs show the first completed sink, so the verdict precedes cleanup.', NULL, NULL, ARRAY['scope', 'publish']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, NULL, NULL, 'const verdict = JSON.parse(process.env.INPUTS_VERDICT);
const report = JSON.parse(process.env.INPUTS_SCOPE_REPORT);
console.log(JSON.stringify(JSON.parse(process.env.INPUTS_HEAD_MATCHES) ? verdict : {
  ready: false, action: "ask",
  findings_summary: require("node:fs").readFileSync(require("node:path").join(process.env.ARTIFACTS_DIR, report.path), "utf8"),
  report, discoveries: [], contract_left: ["PR head mismatch prevented contract review."]
}));
', NULL, 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-review-block', 'prune-scratch', NULL, 14, 'prune-scratch', 'script', 'Reviewers'' scratch worktrees are removed by the workflow once every lens and
the deciding agent have settled, whether they succeeded or failed.', NULL, NULL, ARRAY['synthesize']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, 'prune-scratch', 'review/scripts/prune-scratch.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'forge', NULL, 0, 'forge', 'script', 'Refuses the run before any agent spends when the selected forge source cannot
act: no plugin for the host, no usable credential, or an unauthenticated gh.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'forge-check', 'ship/scripts/forge-check.ts', 'bun', NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'triage', NULL, 1, 'triage', 'include', 'The source is history, not a work order. Triage checks it against current
code and direction before deciding which kind of reasoning is still owed.', NULL, NULL, ARRAY['forge']::text[], NULL, 'archon-triage-block', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'triage/policy', 'triage', 2, 'policy', 'script', 'The directory of the pack''s default policy documents in this run''s captured
source, the same in a source checkout and a binary install. The prompt names the
policy file it needs and reads the default, then the project''s own on top.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'policy', 'triage/scripts/policy.ts', 'bun', NULL, NULL, 'archon-triage-block', 'triage/archon-triage-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'triage/triage', 'triage', 3, 'triage', 'command', NULL, 'medium', NULL, ARRAY['policy']::text[], NULL, NULL, NULL, NULL, 'triage', 'triage/commands/triage.md', NULL, NULL, NULL, NULL, NULL, 'archon-triage-block', 'triage/archon-triage-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'triage/verdict', 'triage', 4, 'verdict', 'script', 'The prompt judges; this boundary flattens the decision into the fields every
caller reads, checks what a schema cannot (blockers are qualified URLs) and
backstops the rest, and
derives the pack''s labels here rather than
chosen by the model: one state label and one type label, plus a size label
while the item can still be worked. Each field''s own type and vocabulary were certified on the
node above. Labels are written only under publish, after the item''s identity
is verified on the tracker, and read back before the node reports them.', NULL, NULL, ARRAY['triage']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'verdict', 'triage/scripts/verdict.ts', 'bun', NULL, NULL, 'archon-triage-block', 'triage/archon-triage-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'inv', NULL, 5, 'inv', 'include', 'Establish the proven causal chain for a bug, unexplained behavior, or open
question — to the root cause whose fix prevents the symptom, never the first
plausible explanation — and write an evidence-backed report a fixer or
planner can act on without repeating the work. Advisory: it reads,
reproduces, and reports — the repository is left exactly as it was found.

Use when: the cause is not yet known — "investigate this issue", "why does
this fail", "root-cause this before we fix it".
NOT for: deciding how to build the fix (plan), or building it (implement).
', NULL, '$triage.output.route == ''investigate''', ARRAY['triage']::text[], NULL, 'archon-investigate', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'inv/investigate', 'inv', 6, 'investigate', 'command', 'Inconclusive is a valid outcome, not a failure: the gaps named honestly beat a
confident guess. Consumers gate on the verdict before building on the chain.', 'medium', NULL, '{}'::text[], NULL, NULL, NULL, NULL, 'investigate', 'investigate/commands/investigate.md', NULL, NULL, NULL, NULL, NULL, 'archon-investigate', 'investigate/archon-investigate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'inv/verdict', 'inv', 7, 'verdict', 'script', NULL, NULL, NULL, ARRAY['investigate']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'verdict', 'investigate/scripts/verdict.ts', 'bun', NULL, NULL, 'archon-investigate', 'investigate/archon-investigate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'intel', NULL, 8, 'intel', 'command', 'Usage data for the planner, when the item could turn on it. The node names no
MCP server, so it runs on every provider and in a repository with no MCP
config; until one is named here it judges relevance and reports that no
source is connected when data would have mattered.', 'medium', '$triage.output.route == ''plan''', ARRAY['triage']::text[], NULL, NULL, NULL, NULL, 'intel', 'ship/commands/intel.md', NULL, NULL, NULL, NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'planned', NULL, 9, 'planned', 'include', 'The planner makes the design calls. Calls it cannot make itself come back as
open questions, which stop the run before delivery.', NULL, '$triage.output.route == ''plan''', ARRAY['triage', 'intel']::text[], NULL, 'archon-plan-block', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'planned/policy', 'planned', 10, 'policy', 'script', 'The directory of the pack''s default policy documents in this run''s captured
source, the same in a source checkout and a binary install. The prompt names the
policy file it needs and reads the default, then the project''s own on top.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'policy', 'plan/scripts/policy.ts', 'bun', NULL, NULL, 'archon-plan-block', 'plan/archon-plan-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'planned/plan', 'planned', 11, 'plan', 'command', 'Open questions are a valid outcome, not a failure: the calls only a person can
make, named, beat a plan built on guesses. Whether the plan is ready is the
planner''s judgment; consumers gate on $plan.output.ready and relay
$plan.output.open_questions either way. A schema cannot tie the two without a
root union, which the providers'' structured output rejects, so the prompt
holds the rule: not ready always names at least one question.', 'large', NULL, ARRAY['policy']::text[], NULL, NULL, NULL, NULL, 'plan', 'plan/commands/plan.md', NULL, NULL, NULL, NULL, NULL, 'archon-plan-block', 'plan/archon-plan-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'continues', NULL, 12, 'continues', 'script', 'The pull request delivery continues has one owner: the caller''s number or `none`
when it resolved one, else triage''s `continue` route. Two different answers
refuse before delivery spends.', NULL, NULL, ARRAY['triage']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'continues', 'ship/scripts/continues.ts', 'bun', NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver', NULL, 13, 'deliver', 'include', 'The delivery tail, autonomous on its green path. Capped rounds of implement
(focused checks only; CI is the full validation), draft PR, and a review at the
depth its risk earns. Once a review passes, simplify judges the structure once,
the implementer adopts or declines its findings, a light review checks what
that changed, and one CI agent marks the PR ready on green. Open review findings,
an unresolved review thread from anyone, a CI red the change caused, or a conflict
with the base send the work back to implement for another round, which merges
the base on a conflict and judges each thread; the round then answers and
resolves the threads it settled. Every other ending is not ready, with
its reason. A red PR never stays ready, nor one with an open thread. Threads are
read through gh; on the forge source the report records them as not checked. Each
round''s pr step publishes description content the round prepared before its
review reads the PR, and the description is corrected and linked once the
rounds end; the report relays discoveries to the operator on every ending,
a failure included. There is no in-run approval
gate — the human gate is PR review and merge on the forge, outside the run.

The graph of archon-deliver, as a building block for a workflow that composes the
stage and owns what follows its ending. It never pauses for a person: run
archon-deliver, which adds that pause, by hand.
', NULL, '$triage.output.route == ''deliver'' || $triage.output.route == ''continue'' || $triage.output.route == ''investigate'' && $inv.output.verdict == ''rooted'' || $triage.output.route == ''plan'' && $planned.output.ready == true', ARRAY['triage', 'continues', 'inv', 'planned']::text[], 'none_failed_min_one_success', 'archon-deliver-block', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/forge', 'deliver', 14, 'forge', 'script', 'Refuses the run before any agent spends when the selected forge source cannot
act: no plugin for the host, no usable credential, or an unauthenticated gh.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'forge-check', 'deliver/scripts/forge-check.ts', 'bun', NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds', 'deliver', 15, 'rounds', 'loop_group', 'One round: implement → draft PR → review → (simplify → reshape → rereview) →
settle-threads → CI → threads. Open review findings, an unresolved review thread, or a red CI the change
caused, start another round. Each
round''s implementer is a fresh agent that reads the previous round''s review
report and ci.md, and each later round''s review reads only its delta. The pr step runs every round, so every round''s commits are
pushed before the review reads the pull request''s remote head.', NULL, NULL, ARRAY['forge']::text[], NULL, NULL, NULL, 4, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/implement', 'deliver/rounds', 16, 'implement', 'include', 'Implement a change and keep working until it is complete and the focused checks
on what it changed pass. Commits as it goes; opens no PR. The input is anything intent-shaped:
a plan (path or inline), review findings, a CI failure to fix, or a plain
description of what to build.

Use when: the work is already decided and needs building — "implement this plan",
"apply these review findings", "build what this describes", "fix this CI failure".
NOT for: deciding what to build, reviewing changes, or opening a PR.
', NULL, NULL, '{}'::text[], NULL, 'archon-implement', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/implement/implement', 'deliver/rounds/implement', 17, 'implement', 'loop', 'Run success ≠ green. The loop completes on `done`, which deliberately includes
a definitive blocked decline (green: false) — so a completed run''s status never
certifies the work. Consumers read $implement.output.green; compositions gate on
it deterministically before spending or shipping (deliver''s pr step does), and the
workflow''s outcome_field records it as the run''s authored outcome.
Each turn is a fresh session: work that continues past a seam is carried by its
commits and implementation.md, never by a conversation that grows with the work.', 'large', NULL, '{}'::text[], NULL, NULL, NULL, NULL, 'implement', 'implement/commands/implement.md', NULL, NULL, NULL, NULL, NULL, 'archon-implement', 'implement/archon-implement.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/pr', 'deliver/rounds', 18, 'pr', 'include', 'Red the change did not cause still goes to review; CI judges it again.', NULL, '$implement.output.green == true || $implement.output.red_cause == ''inherited'' || $implement.output.red_cause == ''environment''', ARRAY['implement']::text[], NULL, 'archon-pr', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/pr/forge', 'deliver/rounds/pr', 19, 'forge', 'script', 'Refuses the run before the agent spends when the selected forge source cannot
act: no plugin for the host, no usable credential, or an unauthenticated gh.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'forge-check', 'pr/scripts/forge-check.ts', 'bun', NULL, NULL, 'archon-pr', 'pr/archon-pr.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/pr/prepare', 'deliver/rounds/pr', 20, 'prepare', 'command', 'The agent judges: which repository the work is proposed to, the base, whether
the run continues an existing pull request, and what the title and body say.
It performs no push and no forge write.', 'medium', NULL, ARRAY['forge']::text[], NULL, NULL, NULL, NULL, 'pr', 'pr/commands/pr.md', NULL, NULL, NULL, NULL, NULL, 'archon-pr', 'pr/archon-pr.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/pr/publish', 'deliver/rounds/pr', 21, 'publish', 'script', 'The durable ownership record for every later public action in delivery and
inbound forge event. It pushes the branch, then opens the pull request, or
reuses the one this work already has; consumers use this qualified identity,
never gh''s ambient branch lookup.', NULL, NULL, ARRAY['prepare']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'publish-pr', 'pr/scripts/publish-pr.ts', 'bun', NULL, NULL, 'archon-pr', 'pr/archon-pr.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/review', 'deliver/rounds', 22, 'review', 'include', 'Review a change through parallel specialist lenses and produce one evidence-based
verdict. On every round but a light one, a quick route agent picks the lenses
the change earns — seams, code, tests, errors, docs — with seams on unless the
change clearly touches no type, contract, state or boundary. Reviews the requested
PR; empty scope selects the current branch''s open PR first, otherwise the working
diff. Every round also holds the change to the accepted contract: each stated
acceptance item, invariant, and steering
constraint is met with cited evidence or raised as a blocking finding. Given a
part assignment, items that only later parts own are deferred, not unmet.
Advisory and read-only: it judges, it never edits. Given the previous round''s
report, the general code reviewer, plus every lens the route agent selects for
a finding the previous round left open or for the delta''s area, reviews only
the correction delta since the reviewed commit, leaving out code a merge of the
base brought in, and judges whether each prior finding was resolved or validly
declined (`light` runs the general code reviewer alone, for a CI fix); one
continuation reviewer carries the prior findings forward.

When the checkout matches the PR head, the final synthesized report is posted
to it as one canonical comment, edited in place on re-review. A head mismatch
stops before review and returns the exact rerun command. For a same-repository
PR, advance any clean existing worktree to its head, then use its head branch.
For a fork PR, fetch its head first, then use a fresh review branch with
`--from <PR head SHA>`.

The graph of archon-review, as a building block for a workflow that composes the
stage and owns what follows its ending. It never pauses for a person: run
archon-review, which adds that pause, by hand.
', NULL, NULL, ARRAY['pr']::text[], NULL, 'archon-review-block', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/review/policy', 'deliver/rounds/review', 23, 'policy', 'script', 'The directory of the pack''s default policy documents in this run''s captured
source, the same in a source checkout and a binary install. Synthesis names the
policy file it needs and reads the default, then the project''s own on top.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'policy', 'review/scripts/policy.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/review/mode', 'deliver/rounds/review', 24, 'mode', 'script', 'After scope accepts the checkout, fixes what this round reviews: whether it
continues a previous round, the commit under review (the checkout''s HEAD as
the engine observed it), and, on a continuation, the previous round''s
reviewed commit, which the head must descend from. A caller''s pull-request
record names the PR, never the commit: its head revision goes stale with
every push after the PR opens. publish refuses a report about any other
commit. The node also turns the input into the routable fact the lenses gate
on: an include''s inputs are substituted as text at load time and cannot be
compared in a `when:`. For the same reason it carries the part assignment, so
synthesis reads a value certified against its schema, not raw text.', NULL, '$scope.output.head_matches == true', ARRAY['scope']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'review-round', 'review/scripts/review-round.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/review/review-dir', 'deliver/rounds/review', 25, 'review-dir', 'bash', 'Every review node writes under review/, and a fresh run''s artifacts directory
has none. Agents told to create it have skipped that step, so the declared
scope.md pointer failed and took the whole delivery run down with it.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'mkdir -p "$ARTIFACTS_DIR/review"', NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/review/scope', 'deliver/rounds/review', 26, 'scope', 'command', NULL, 'medium', NULL, ARRAY['review-dir']::text[], NULL, NULL, NULL, NULL, 'review-scope', 'review/commands/review-scope.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/review/route', 'deliver/rounds/review', 27, 'route', 'command', 'After scope checks the head, a small model reads the diff
summary and the work order and answers, with seams on by default. Every round
but a light one routes; on a continuation route adds to the code lens every lens
whose finding the previous report leaves open or whose area the delta touches.', 'small', '$scope.output.head_matches == true && $mode.output.light == false', ARRAY['mode', 'scope']::text[], NULL, NULL, NULL, NULL, 'route-review', 'review/commands/route-review.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/review/seams', 'deliver/rounds/review', 28, 'seams', 'command', '── Lenses ────────────────────────────────────────────────────────
Every reviewer is read-only by the engine''s check, not only by its prompt:
lenses run in parallel in one checkout, so a reviewer that edits it can
mislead the others. `&&` binds tighter than `||` and short-circuits, so a
light round, which skips the route node, never reads it.', 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.seams == true || $scope.output.head_matches == true && $mode.output.seams == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-seams', 'review/commands/review-seams.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/review/code', 'deliver/rounds/review', 29, 'code', 'command', NULL, 'large', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.code == true || $scope.output.head_matches == true && $mode.output.code == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-code', 'review/commands/review-code.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/review/tests', 'deliver/rounds/review', 30, 'tests', 'command', NULL, 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.tests == true || $scope.output.head_matches == true && $mode.output.tests == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-tests', 'review/commands/review-tests.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/review/errors', 'deliver/rounds/review', 31, 'errors', 'command', NULL, 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.errors == true || $scope.output.head_matches == true && $mode.output.errors == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-errors', 'review/commands/review-errors.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/review/docs', 'deliver/rounds/review', 32, 'docs', 'command', NULL, 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.docs == true || $scope.output.head_matches == true && $mode.output.docs == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-docs', 'review/commands/review-docs.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/review/review-complete', 'deliver/rounds/review', 33, 'review-complete', 'bash', 'all_done lets this barrier settle after unselected lenses, or a lens whose
retries were exhausted. The deciding
agent can then tolerate specialist failures without also tolerating a failed
mode/scope preflight: synthesize separately requires both to have succeeded.', NULL, '$scope.output.head_matches == true', ARRAY['scope', 'route', 'seams', 'code', 'tests', 'errors', 'docs']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'true', NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/review/synthesize', 'deliver/rounds/review', 34, 'synthesize', 'command', 'A failed specialist (a provider stream dying mid-review, say) must not kill
the review: synthesize detects the missing completion for a selected lens and
forces ready:false naming the gap, so degradation is disclosed, never silent,
and the next round is the retry. `ready` is a real boolean — the load-bearing field a composing
loop terminates on. Every round receives this round''s lens files; a
continuation also receives the complete prior report and correction delta.

The deciding agent and the lenses start fresh and carry earlier rounds through
the prior report, not a resumed session: a loop body cannot resume a session
from its own earlier iteration, and session resume is not portable across the
bundle''s supported providers (Claude Code, Codex, and Pi).

Adversarial per-finding verification happens inside this node''s prompt. A
separate verify stage between the lenses and this node is now expressible and
would not change either side''s contract — the findings files are the declared
boundary — but nothing has measured it as better than the in-prompt pass, so
it stays here until something does.', 'medium', '$scope.output.head_matches == true', ARRAY['policy', 'mode', 'scope', 'review-complete']::text[], NULL, NULL, NULL, NULL, 'review-synthesize', 'review/commands/review-synthesize.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/review/publish', 'deliver/rounds/review', 35, 'publish', 'script', 'The reviewer judges and writes the report; this node owns the one public
write, so every round edits the same marked comment instead of appending
another, through whichever forge source the run selected. The verdict passes
through unchanged: publication is not what makes a review true.', NULL, '$scope.output.head_matches == true', ARRAY['synthesize']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'publish-review', 'review/scripts/publish-review.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/review/result', 'deliver/rounds/review', 36, 'result', 'script', 'Standalone runs show the first completed sink, so the verdict precedes cleanup.', NULL, NULL, ARRAY['scope', 'publish']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, NULL, NULL, 'const verdict = JSON.parse(process.env.INPUTS_VERDICT);
const report = JSON.parse(process.env.INPUTS_SCOPE_REPORT);
console.log(JSON.stringify(JSON.parse(process.env.INPUTS_HEAD_MATCHES) ? verdict : {
  ready: false, action: "ask",
  findings_summary: require("node:fs").readFileSync(require("node:path").join(process.env.ARTIFACTS_DIR, report.path), "utf8"),
  report, discoveries: [], contract_left: ["PR head mismatch prevented contract review."]
}));
', NULL, 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/review/prune-scratch', 'deliver/rounds/review', 37, 'prune-scratch', 'script', 'Reviewers'' scratch worktrees are removed by the workflow once every lens and
the deciding agent have settled, whether they succeeded or failed.', NULL, NULL, ARRAY['synthesize']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, 'prune-scratch', 'review/scripts/prune-scratch.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/simplify', 'deliver/rounds', 38, 'simplify', 'include', 'After a review passes, before CI. Once per run: a later round finds the
earlier shape.md and declares no findings (see simplify.md).', NULL, '$review.output.ready == true', ARRAY['review']::text[], NULL, 'archon-simplify', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/simplify/simplify', 'deliver/rounds/simplify', 39, 'simplify', 'command', NULL, 'medium', NULL, '{}'::text[], NULL, NULL, NULL, NULL, 'simplify', 'simplify/commands/simplify.md', NULL, NULL, NULL, NULL, NULL, 'archon-simplify', 'simplify/archon-simplify.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/simplify/prune-scratch', 'deliver/rounds/simplify', 40, 'prune-scratch', 'script', 'Scratch worktrees the lens tried mutations in are removed by the workflow,
whether the lens succeeded or failed.', NULL, NULL, ARRAY['simplify']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, 'prune-scratch', 'simplify/scripts/prune-scratch.ts', 'bun', NULL, NULL, 'archon-simplify', 'simplify/archon-simplify.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/reshape', 'deliver/rounds', 41, 'reshape', 'include', 'Implement a change and keep working until it is complete and the focused checks
on what it changed pass. Commits as it goes; opens no PR. The input is anything intent-shaped:
a plan (path or inline), review findings, a CI failure to fix, or a plain
description of what to build.

Use when: the work is already decided and needs building — "implement this plan",
"apply these review findings", "build what this describes", "fix this CI failure".
NOT for: deciding what to build, reviewing changes, or opening a PR.
', NULL, '$simplify.output.findings == true', ARRAY['simplify']::text[], NULL, 'archon-implement', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/reshape/implement', 'deliver/rounds/reshape', 42, 'implement', 'loop', 'Run success ≠ green. The loop completes on `done`, which deliberately includes
a definitive blocked decline (green: false) — so a completed run''s status never
certifies the work. Consumers read $implement.output.green; compositions gate on
it deterministically before spending or shipping (deliver''s pr step does), and the
workflow''s outcome_field records it as the run''s authored outcome.
Each turn is a fresh session: work that continues past a seam is carried by its
commits and implementation.md, never by a conversation that grows with the work.', 'large', NULL, '{}'::text[], NULL, NULL, NULL, NULL, 'implement', 'implement/commands/implement.md', NULL, NULL, NULL, NULL, NULL, 'archon-implement', 'implement/archon-implement.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/rereview', 'deliver/rounds', 43, 'rereview', 'include', 'Reshape commits after review passed, so its delta is reviewed before CI, by
the light review a CI fix gets: the code lens alone, on the delta.', NULL, NULL, ARRAY['reshape']::text[], NULL, 'archon-review-block', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/rereview/policy', 'deliver/rounds/rereview', 44, 'policy', 'script', 'The directory of the pack''s default policy documents in this run''s captured
source, the same in a source checkout and a binary install. Synthesis names the
policy file it needs and reads the default, then the project''s own on top.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'policy', 'review/scripts/policy.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/rereview/mode', 'deliver/rounds/rereview', 45, 'mode', 'script', 'After scope accepts the checkout, fixes what this round reviews: whether it
continues a previous round, the commit under review (the checkout''s HEAD as
the engine observed it), and, on a continuation, the previous round''s
reviewed commit, which the head must descend from. A caller''s pull-request
record names the PR, never the commit: its head revision goes stale with
every push after the PR opens. publish refuses a report about any other
commit. The node also turns the input into the routable fact the lenses gate
on: an include''s inputs are substituted as text at load time and cannot be
compared in a `when:`. For the same reason it carries the part assignment, so
synthesis reads a value certified against its schema, not raw text.', NULL, '$scope.output.head_matches == true', ARRAY['scope']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'review-round', 'review/scripts/review-round.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/rereview/review-dir', 'deliver/rounds/rereview', 46, 'review-dir', 'bash', 'Every review node writes under review/, and a fresh run''s artifacts directory
has none. Agents told to create it have skipped that step, so the declared
scope.md pointer failed and took the whole delivery run down with it.', NULL, NULL, '{}'::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'mkdir -p "$ARTIFACTS_DIR/review"', NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/rereview/scope', 'deliver/rounds/rereview', 47, 'scope', 'command', NULL, 'medium', NULL, ARRAY['review-dir']::text[], NULL, NULL, NULL, NULL, 'review-scope', 'review/commands/review-scope.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/rereview/route', 'deliver/rounds/rereview', 48, 'route', 'command', 'After scope checks the head, a small model reads the diff
summary and the work order and answers, with seams on by default. Every round
but a light one routes; on a continuation route adds to the code lens every lens
whose finding the previous report leaves open or whose area the delta touches.', 'small', '$scope.output.head_matches == true && $mode.output.light == false', ARRAY['mode', 'scope']::text[], NULL, NULL, NULL, NULL, 'route-review', 'review/commands/route-review.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/rereview/seams', 'deliver/rounds/rereview', 49, 'seams', 'command', '── Lenses ────────────────────────────────────────────────────────
Every reviewer is read-only by the engine''s check, not only by its prompt:
lenses run in parallel in one checkout, so a reviewer that edits it can
mislead the others. `&&` binds tighter than `||` and short-circuits, so a
light round, which skips the route node, never reads it.', 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.seams == true || $scope.output.head_matches == true && $mode.output.seams == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-seams', 'review/commands/review-seams.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/rereview/code', 'deliver/rounds/rereview', 50, 'code', 'command', NULL, 'large', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.code == true || $scope.output.head_matches == true && $mode.output.code == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-code', 'review/commands/review-code.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/rereview/tests', 'deliver/rounds/rereview', 51, 'tests', 'command', NULL, 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.tests == true || $scope.output.head_matches == true && $mode.output.tests == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-tests', 'review/commands/review-tests.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/rereview/errors', 'deliver/rounds/rereview', 52, 'errors', 'command', NULL, 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.errors == true || $scope.output.head_matches == true && $mode.output.errors == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-errors', 'review/commands/review-errors.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/rereview/docs', 'deliver/rounds/rereview', 53, 'docs', 'command', NULL, 'medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.docs == true || $scope.output.head_matches == true && $mode.output.docs == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-docs', 'review/commands/review-docs.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/rereview/review-complete', 'deliver/rounds/rereview', 54, 'review-complete', 'bash', 'all_done lets this barrier settle after unselected lenses, or a lens whose
retries were exhausted. The deciding
agent can then tolerate specialist failures without also tolerating a failed
mode/scope preflight: synthesize separately requires both to have succeeded.', NULL, '$scope.output.head_matches == true', ARRAY['scope', 'route', 'seams', 'code', 'tests', 'errors', 'docs']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'true', NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/rereview/synthesize', 'deliver/rounds/rereview', 55, 'synthesize', 'command', 'A failed specialist (a provider stream dying mid-review, say) must not kill
the review: synthesize detects the missing completion for a selected lens and
forces ready:false naming the gap, so degradation is disclosed, never silent,
and the next round is the retry. `ready` is a real boolean — the load-bearing field a composing
loop terminates on. Every round receives this round''s lens files; a
continuation also receives the complete prior report and correction delta.

The deciding agent and the lenses start fresh and carry earlier rounds through
the prior report, not a resumed session: a loop body cannot resume a session
from its own earlier iteration, and session resume is not portable across the
bundle''s supported providers (Claude Code, Codex, and Pi).

Adversarial per-finding verification happens inside this node''s prompt. A
separate verify stage between the lenses and this node is now expressible and
would not change either side''s contract — the findings files are the declared
boundary — but nothing has measured it as better than the in-prompt pass, so
it stays here until something does.', 'medium', '$scope.output.head_matches == true', ARRAY['policy', 'mode', 'scope', 'review-complete']::text[], NULL, NULL, NULL, NULL, 'review-synthesize', 'review/commands/review-synthesize.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/rereview/publish', 'deliver/rounds/rereview', 56, 'publish', 'script', 'The reviewer judges and writes the report; this node owns the one public
write, so every round edits the same marked comment instead of appending
another, through whichever forge source the run selected. The verdict passes
through unchanged: publication is not what makes a review true.', NULL, '$scope.output.head_matches == true', ARRAY['synthesize']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'publish-review', 'review/scripts/publish-review.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/rereview/result', 'deliver/rounds/rereview', 57, 'result', 'script', 'Standalone runs show the first completed sink, so the verdict precedes cleanup.', NULL, NULL, ARRAY['scope', 'publish']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, NULL, NULL, 'const verdict = JSON.parse(process.env.INPUTS_VERDICT);
const report = JSON.parse(process.env.INPUTS_SCOPE_REPORT);
console.log(JSON.stringify(JSON.parse(process.env.INPUTS_HEAD_MATCHES) ? verdict : {
  ready: false, action: "ask",
  findings_summary: require("node:fs").readFileSync(require("node:path").join(process.env.ARTIFACTS_DIR, report.path), "utf8"),
  report, discoveries: [], contract_left: ["PR head mismatch prevented contract review."]
}));
', NULL, 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/rereview/prune-scratch', 'deliver/rounds/rereview', 58, 'prune-scratch', 'script', 'Reviewers'' scratch worktrees are removed by the workflow once every lens and
the deciding agent have settled, whether they succeeded or failed.', NULL, NULL, ARRAY['synthesize']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, 'prune-scratch', 'review/scripts/prune-scratch.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/settle-threads', 'deliver/rounds', 59, 'settle-threads', 'command', 'Review threads are work too, whoever opened them. This round''s implementer
judged the threads the previous round read; this agent checks each
disposition at the head and writes the reply each settled thread gets.', 'medium', '$LOOP_PREV.threads.output.open > 0', ARRAY['pr', 'review', 'rereview']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'settle-threads', 'deliver/commands/settle-threads.md', NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/ci', 'deliver/rounds', 60, 'ci', 'command', 'CI is the project''s full validation: implementers run only focused checks.
Fresh: CI reads the PR, not simplify''s or reshape''s conversation.', 'medium', '$review.output.ready == true && $simplify.output.findings == false || $review.output.ready == true && $simplify.output.findings == true && $rereview.output.ready == true', ARRAY['review', 'simplify', 'rereview', 'settle-threads']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'ci', 'deliver/commands/ci.md', NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/threads', 'deliver/rounds', 61, 'threads', 'script', 'Posts and resolves settle-threads'' answers, then reads what is still open,
after CI so threads posted during the round count.', NULL, NULL, ARRAY['pr', 'review', 'rereview', 'ci', 'settle-threads']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, NULL, NULL, 'threads', 'deliver/scripts/threads.ts', 'bun', NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/rounds/round', 'deliver/rounds', 62, 'round', 'script', '`until_bash` and the loop''s output cannot read a skipped node, so this joins
the round''s verdicts into the value the loop decides on.', NULL, NULL, ARRAY['implement', 'pr', 'review', 'rereview', 'ci', 'threads']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, 'round', 'deliver/scripts/round.ts', 'bun', NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/update-pr-body', 'deliver', 63, 'update-pr-body', 'command', 'Corrections and the base merge can falsify claims the description made when the
draft opened, and an implementer can pass red the description must disclose. One
agent reads the live description and the final diff, and edits only what is no
longer true. It also links the issue by the latest review''s coverage: closing
only when nothing is left. It runs once the rounds have ended, never per round;
content a round prepared for the description is that round''s pr step''s write.', 'medium', '$rounds.output.pr_url != ''''', ARRAY['rounds']::text[], NULL, NULL, NULL, NULL, 'update-pr-body', 'deliver/commands/update-pr-body.md', NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/outcome', 'deliver', 64, 'outcome', 'script', 'Composes the success-path report (scripts/outcome.ts): ready with the pull
request''s URL, or not ready with why. `report` relays it.', NULL, NULL, ARRAY['rounds', 'update-pr-body']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, NULL, NULL, 'outcome', 'deliver/scripts/outcome.ts', 'bun', NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'deliver/report', 'deliver', 65, 'report', 'script', 'The workflow''s terminal report on every ending. A node failure skips `outcome`
(never fails it), so `all_done` still runs this node and the binding reads null.
`always_run` because it reads discoveries its dependency edge does not carry.', NULL, NULL, ARRAY['outcome']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, 'report', 'deliver/scripts/report.ts', 'bun', NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'outcome', NULL, 66, 'outcome', 'script', 'The result of every legitimate ending, relayed by `report`. Negative advisory verdicts
complete with the report that explains them; a delivery is reported from the
deliver branch''s own outcome, ready or not (bound with if_skipped, so a skipped
branch arrives as null) — see scripts/outcome.ts.

The advisory producers are bound with if_skipped: a route that never ran them
reads null. Two dependencies carry the whole graph. `deliver` depends on triage,
inv and planned, so nothing this node reports on can settle after it. `triage` is named because
none_failed_min_one_success needs one completed dependency, and on the no_action
route `deliver` is the skipped one.

A failed delivery reaches this node through deliver''s report (`reason: failed`
or `pr_create_unresolved`) and is relayed like any other not-ready delivery. A
failure before delivery skips this node, and `report` answers.', NULL, NULL, ARRAY['triage', 'deliver']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, NULL, NULL, 'outcome', 'ship/scripts/outcome.ts', 'bun', NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'report', NULL, 67, 'report', 'script', 'The workflow''s terminal report on every ending. A node failure skips `outcome`
(never fails it), so `all_done` still runs this node and the binding reads null.
`always_run` because it reads discoveries its dependency edge does not carry.', NULL, NULL, ARRAY['outcome']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, 'report', 'ship/scripts/report.ts', 'bun', NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
