INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-validate', 'compare', NULL, 1, 'compare', 'script', NULL, NULL, '$mode.output.comparison == true', ARRAY['mode']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'compare', 'validate/scripts/compare.ts', 'bun', NULL, NULL, 'archon-validate', 'validate/archon-validate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-validate', 'applicability', NULL, 2, 'applicability', 'script', 'A run that reaches validation again after a pause (an approval, a CI wait, an
operator''s resume) reuses the verdict it already reached when nothing that
verdict measured has changed: the tracked tree, scope, context, this validator''s
own sources and the recorded report. Decided on every pass, never cached, and
only a green verdict with performed checks is ever reused. The rules are in
.shared/validation-evidence.ts.', NULL, '$mode.output.comparison == false', ARRAY['mode']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'applicability', 'validate/scripts/applicability.ts', 'bun', NULL, NULL, 'archon-validate', 'validate/archon-validate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-validate', 'discover', NULL, 3, 'discover', 'command', 'Ordinary validation is three nodes. Finding the gate is judgement, so an agent
does it. Running the gate is computation, so a script does it: an agent''s
shell tool has a per-call time limit that a project''s gate can outlast, and a
script node runs for as long as its own `timeout:` allows. Judging why a
check failed is judgement again, so only a red run reaches an agent.', 'medium', '$applicability.output.reuse == false', ARRAY['applicability']::text[], NULL, NULL, NULL, NULL, 'discover-checks', 'validate/commands/discover-checks.md', NULL, NULL, NULL, NULL, NULL, 'archon-validate', 'validate/archon-validate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-validate', 'run', NULL, 4, 'run', 'script', 'Runs the declared checks and records every exit status in
`$ARTIFACTS_DIR/validation.md`. Green and "didn''t finish" are read from those
exit statuses, never from a clock. The timeout is sized for a slow gate on a
loaded machine. When it stops the gate anyway, the node is skipped and
`result` reports `incomplete`.', NULL, NULL, ARRAY['discover']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'run-checks', 'validate/scripts/run-checks.ts', 'bun', NULL, NULL, 'archon-validate', 'validate/archon-validate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-validate', 'classify', NULL, 5, 'classify', 'command', NULL, 'medium', '$run.output.status == ''red''', ARRAY['run']::text[], NULL, NULL, NULL, NULL, 'classify-red', 'validate/commands/classify-red.md', NULL, NULL, NULL, NULL, NULL, 'archon-validate', 'validate/archon-validate.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-validate', 'result', NULL, 6, 'result', 'script', 'The one verdict. A fresh ordinary verdict is recorded here as evidence, with
