INSERT INTO mc.arch_edges (archon_sha, factory_sha, workflow, from_path, to_path) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'factory-backlog', 'slice', 'check');
