INSERT INTO mc.arch_hooks (archon_sha, factory_sha, path, text, admitted_agents) VALUES ('abd85896e7971c9ac5199ed7e87973f27130250f', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '.factory/hooks/holdout_fence.py', '"""The holdout fence: only the holdout subagents may see .factory/holdout/, and nothing may change the fence.

Claude Code runs this before every tool call (`pre`) and tags each call a subagent makes with its
`agent_type`. Calls from `holdout-writer` and `holdout-verifier` pass. Every other call (builders,
reviewers, the manager itself, a human session) is refused, by exit 2, when it would show a scenario:

- it names the folder or a HOLDOUT.md, or globs into `.factory`;
- it is a recursive search whose scope covers the folder. The Grep and Glob tools skip the folder
  through `.ignore`; shell `grep -r`, `git grep` and `rg --no-ignore` do not;
- it is a `git diff`, `git log -p` or `git show` whose output would include a file in the folder.
  Git is asked with `--name-only`, so a command that cannot reach the folder is never refused.

Any call that would change the fence itself (this folder, `.claude/settings.json`, `.ignore`) is
refused for everyone. After each call (`post`) the result is checked for scenario text, and a hit is
appended to `holdout-exposures.jsonl` in the repository''s git directory, so a leak the fence did not
foresee is counted instead of invisible.

Claude Code lets a call through when a hook errors, so `pre` fails closed: an error is a refusal.
"""

import json
import os
import re
import shlex
import subprocess
import sys
import time
from pathlib import Path

HOLDOUT_AGENTS = {"holdout-writer", "holdout-verifier"}
FOLDER = ".factory/holdout"
# Tools that read, search or change files, or hand work to another agent. Output-only tools
# (StructuredOutput, TodoWrite, ...) are never refused for mentioning the folder.
ACCESS_TOOLS = {"Bash", "PowerShell", "Read", "Grep", "Glob", "Edit", "Write", "MultiEdit",
                "NotebookEdit", "NotebookRead", "Agent", "Task"}
WRITE_TOOLS = {"Edit", "Write", "MultiEdit", "NotebookEdit"}
SHELL_TOOLS = {"Bash", "PowerShell"}

NAMED = re.compile(r"\.factory/+(?:holdout(?![\w-])|[*?\[])|(?<![\w-])holdout\.md\b", re.I)
FENCE = re.compile(r"\.factory/+hooks(?![\w-])|\.claude/+settings(?:\.local)?\.json|(?<![\w.])\.ignore\b", re.I)
MUTATES = re.compile(
    r">|\btee\b|\b(?:sed|perl)\s+-\w*i|\b(?:rm|mv|cp|chmod|truncate|ln|install)\b|"
    r"\bgit\s+(?:checkout|restore|rm|mv|reset|stash)\b|Set-Content|Add-Content|Out-File|"
    r"Remove-Item|Move-Item|Copy-Item|Rename-Item", re.I)
SEGMENT = re.compile(r"\s*(?:&&|\|\||;|\||\n)\s*")
NO_PATCH = {"--stat", "--name-only", "--name-status", "--numstat", "--shortstat", "--summary",
            "-s", "--no-patch", "--quiet", "--exit-code", "--raw"}
LOG_PATCH = re.compile(r"^(?:-p|--patch|-u|-U\d*|--unified(?:=\d+)?|--full-diff|-m|--cc|-c)$")
PROBE_DROP = re.compile(r"^(?:-p|--patch|-u|-U\d*|--unified(?:=\d+)?|--stat(?:=.*)?|--color(?:=.*)?|"
                        r"--format(?:=.*)?|--pretty(?:=.*)?|--oneline|--graph|-w|--word-diff(?:=.*)?)$")
GREP_ARG_OPTS = {"-e", "-f", "-A", "-B", "-C", "-m", "-d", "-D", "--context", "--max-count", "--include",
                 "--exclude", "--exclude-dir", "--regexp", "--file"}


def refuse(reason: str) -> None:
    print(f"Blocked by the holdout fence: {reason}. The holdout scenarios are for the "
          "holdout-verifier and holdout-writer subagents only; scope searches and diffs to source "
          "folders (or exclude .factory).", file=sys.stderr)
    sys.exit(2)


def normal(path: str) -> str:
    """A comparable absolute path: forward slashes, Git Bash drive form folded, case folded on Windows."""
    path = path.strip().strip("''\"").replace("\\", "/")
    drive = re.match(r"^/([a-zA-Z])(/|$)", path)
    if drive and os.name == "nt":
        path = f"{drive.group(1)}:/{path[3:]}"
    path = os.path.normpath(os.path.expanduser(path)).replace("\\", "/")
    return path.lower() if os.name == "nt" else path


def resolve(path: str, cwd: str) -> str:
    path = path.strip().strip("''\"")
    static = re.split(r"[*?\[{]", path, maxsplit=1)[0]
    if static != path:
        static = static.rsplit("/", 1)[0] if "/" in static else ""
    raw = static.replace("\\", "/")
    if raw == "" or not (raw.startswith("/") or re.match(r"^[a-zA-Z]:", raw) or raw.startswith("~")):
        raw = os.path.join(cwd, raw) if raw else cwd
    return normal(raw)


def covers(path: str, holdout: str) -> bool:
    path = path.rstrip("/")
    return holdout == path or holdout.startswith(path + "/")


def tokens(segment: str, posix: bool = True) -> list[str]:
    try:
        words = [w.strip("''\"") for w in shlex.split(segment, posix=posix)]
    except ValueError:
        words = segment.split()
    while words and re.match(r"^\w+=", words[0]):
        words = words[1:]
    return words


def excluded(words: list[str]) -> bool:
    """The search excludes .factory (or the holdout folder) itself."""
    text = " ".join(words).replace("\\", "/")
    return bool(re.search(r"(--exclude-dir[= ]\S*(\.factory|holdout|\.\*))|(:\(exclude\)|:!|:\^)\S*\.factory"
                          r"|(-g|--glob)[= ][''\"]?!\S*\.factory", text, re.I))


def grep_paths(args: list[str]) -> tuple[bool, list[str]]:
    recursive, positional, has_pattern_opt, skip = False, [], False, False
    for index, arg in enumerate(args):
        if skip:
            skip = False
            continue
        if arg == "--":
            positional.extend(args[index + 1:])
            break
        if arg.startswith("--"):
            recursive |= arg in ("--recursive", "--dereference-recursive")
            has_pattern_opt |= arg.startswith(("--regexp", "--file"))
            skip = arg in GREP_ARG_OPTS
        elif arg.startswith("-") and len(arg) > 1:
            letters = arg[1:]
            recursive |= "r" in letters or "R" in letters
            has_pattern_opt |= "e" in letters or "f" in letters
            skip = arg in GREP_ARG_OPTS or letters[-1:] in ("e", "f", "A", "B", "C", "m")
        else:
            positional.append(arg)
    paths = positional if has_pattern_opt else positional[1:]
    return recursive, paths


def git_probe(words: list[str], cwd: str, holdout_rel: str) -> bool:
    """Whether a git diff/log/show would print a file under the holdout folder."""
    index, base = 1, cwd
    while index < len(words) and words[index].startswith("-"):
        if words[index] in ("-C", "-c") and index + 1 < len(words):
            base = resolve(words[index + 1], cwd) if words[index] == "-C" else base
            index += 2
        else:
            index += 1
    if index >= len(words) or words[index] not in ("diff", "log", "show", "whatchanged"):
        return False
    sub, rest = words[index], words[index + 1:]
    if any(arg in NO_PATCH for arg in rest) and not any(LOG_PATCH.match(arg) for arg in rest):
        return False
    if sub in ("log", "whatchanged") and not any(LOG_PATCH.match(arg) for arg in rest):
        return False
    probe = ["git", "-C", base, sub, "--name-only"] + (["--format="] if sub != "diff" else [])
    probe += [arg for arg in rest if not PROBE_DROP.match(arg)]
    try:
        out = subprocess.run(probe, capture_output=True, text=True, timeout=20).stdout
    except (OSError, subprocess.SubprocessError):
        return False
    return any(line.strip().replace("\\", "/").startswith(holdout_rel + "/") for line in out.splitlines())


def check_shell(command: str, cwd: str, holdout: str, posix: bool) -> None:
    for segment in SEGMENT.split(command):
        words = tokens(segment, posix)
        if not words:
            continue
        program = words[0].rsplit("/", 1)[-1].lower()
        if program == "cd" and len(words) > 1:
            cwd = resolve(words[1], cwd)
            continue
        if program in ("grep", "egrep", "fgrep"):
            recursive, paths = grep_paths(words[1:])
            if recursive and not excluded(words) and any(covers(resolve(p, cwd), holdout) for p in paths or ["."]):
                refuse(f"`{segment.strip()[:80]}` searches the folder")
        elif program == "rg":
            no_ignore = any(re.match(r"^(-u+|--no-ignore(-dot|-files|-vcs)?)$", w) for w in words[1:])
            if no_ignore and not excluded(words):
                paths = [w for w in words[1:] if not w.startswith("-")][1:]
                if any(covers(resolve(p, cwd), holdout) for p in paths or ["."]):
                    refuse(f"`{segment.strip()[:80]}` searches the folder without .ignore")
        elif program == "git" and "grep" in words[1:3]:
            rest = words[words.index("grep") + 1:]
            specs = rest[rest.index("--") + 1:] if "--" in rest else []
            if not excluded(words) and any(covers(resolve(p, cwd), holdout) for p in specs or ["."]):
                refuse(f"`{segment.strip()[:80]}` searches the folder")
        elif program == "git" and git_probe(words, cwd, FOLDER):
            refuse(f"`{segment.strip()[:80]}` would print a holdout file")


def pre(event: dict) -> None:
    tool = event.get("tool_name", "")
    tool_input = event.get("tool_input") or {}
    text = json.dumps(tool_input).replace("\\\\", "/")
    holdout_agent = event.get("agent_type") in HOLDOUT_AGENTS
    target = json.dumps([tool_input.get(key, "") for key in ("file_path", "notebook_path")]).replace("\\\\", "/")
    if tool in WRITE_TOOLS and FENCE.search(target):
        refuse("the fence itself only changes by hand")
    if tool in SHELL_TOOLS and FENCE.search(text) and MUTATES.search(tool_input.get("command", "")):
        refuse("the fence itself only changes by hand")
    if holdout_agent or tool not in ACCESS_TOOLS:
        return
    if tool in ("Agent", "Task") and tool_input.get("subagent_type") in HOLDOUT_AGENTS:
        return
    if NAMED.search(text):
        refuse("the call names the holdout folder")
    if tool in SHELL_TOOLS:
        root = normal(os.environ.get("CLAUDE_PROJECT_DIR") or event.get("cwd") or os.getcwd())
        cwd = normal(event.get("cwd") or root)
        check_shell(tool_input.get("command", ""), cwd, f"{root}/{FOLDER}", tool == "Bash")


def strings(value) -> list[str]:
    if isinstance(value, str):
        return [value]
    if isinstance(value, dict):
        return [s for item in value.values() for s in strings(item)]
    if isinstance(value, list):
        return [s for item in value for s in strings(item)]
    return []


def squash(text: str) -> str:
    return " ".join(text.lower().split())


def post(event: dict) -> None:
    if event.get("agent_type") in HOLDOUT_AGENTS:
        return
    root = Path(os.environ.get("CLAUDE_PROJECT_DIR") or event.get("cwd") or os.getcwd())
    scenarios = root / FOLDER / "HOLDOUT.md"
    if not scenarios.is_file():
        return
    current, prints = "", {}
    for line in scenarios.read_text(encoding="utf-8", errors="replace").splitlines():
        heading = re.match(r"^#{2,3}\s+(\S+)", line)
        if heading:
            current = heading.group(1)
        flat = squash(line.lstrip("#"))
        if len(flat) >= 40:
            prints[flat] = current
    seen = squash("\n".join(strings(event.get("tool_response"))))
    hits = sorted({scenario for flat, scenario in prints.items() if flat in seen})
    if not hits:
        return
    common = subprocess.run(["git", "rev-parse", "--git-common-dir"], cwd=root, capture_output=True,
                            text=True, timeout=20).stdout.strip()
    log = (root / common if common else root / ".git") / "holdout-exposures.jsonl"
    with open(log, "a", encoding="utf-8") as handle:
        handle.write(json.dumps({"at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                                 "session": event.get("session_id", ""), "agent": event.get("agent_type", ""),
                                 "tool": event.get("tool_name", ""), "scenarios": hits}) + "\n")


def main() -> None:
    mode = sys.argv[1] if len(sys.argv) > 1 else "pre"
    try:
        event = json.load(sys.stdin)
        (post if mode == "post" else pre)(event)
    except SystemExit:
        raise
    except Exception as error:  # noqa: BLE001 - any failure must refuse, never let the call through
        if mode == "post":
            sys.exit(0)
        refuse(f"the fence could not check this call ({type(error).__name__}: {error})")
    sys.exit(0)


if __name__ == "__main__":
    main()
', ARRAY['holdout-writer', 'holdout-verifier']::text[]);

-- V2: V1's rows copied, then every row V2_EDITS changed replaced.
INSERT INTO mc.arch_versions (archon_sha, factory_sha, parsed_at) VALUES ('2b7c4e9a1f0d3c5b6a7e8f9d0c1b2a3f4e5d6c7b', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '2026-10-10T00:00:00Z');
INSERT INTO mc.arch_workflows (archon_sha, factory_sha, name, description, model, file, yaml) SELECT '2b7c4e9a1f0d3c5b6a7e8f9d0c1b2a3f4e5d6c7b', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', name, description, model, file, yaml FROM mc.arch_workflows WHERE archon_sha = 'abd85896e7971c9ac5199ed7e87973f27130250f' AND factory_sha = '6311108f789119a8a1a6a7c77ece21ca3a75c3e8';
DELETE FROM mc.arch_workflows WHERE archon_sha = '2b7c4e9a1f0d3c5b6a7e8f9d0c1b2a3f4e5d6c7b' AND factory_sha = '6311108f789119a8a1a6a7c77ece21ca3a75c3e8' AND name = 'archon-loop';
DELETE FROM mc.arch_workflows WHERE archon_sha = '2b7c4e9a1f0d3c5b6a7e8f9d0c1b2a3f4e5d6c7b' AND factory_sha = '6311108f789119a8a1a6a7c77ece21ca3a75c3e8' AND name = 'archon-manager';
INSERT INTO mc.arch_workflows (archon_sha, factory_sha, name, description, model, file, yaml) VALUES ('2b7c4e9a1f0d3c5b6a7e8f9d0c1b2a3f4e5d6c7b', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-loop', 'One unattended move on a repository. A pick agent reads the whole board (open
pull requests, CI, review comments, issues) and chooses the single most
valuable move and its route: finish an open pull request or build a contained
change in the loop, or take complex work through archon-ship-block. Two independent
reviewers then check the result: one runs the app as a user would, against the
acceptance contract and any reviewer-only holdout scenarios, without reading
the diff first; the other reads the diff and decides to merge it head-pinned,
send it back with evidence, or return it to the owner. All state lives in
GitHub, so the next run picks up where this one left off.

Use when: a scheduler should keep a backlog moving with nobody at the
keyboard — "keep building", "run the loop".
NOT for: slicing a product document into issues (archon-backlog).
', 'large', 'loop/archon-loop.yaml', 'name: archon-loop
description: |
  One unattended move on a repository. A pick agent reads the whole board (open
  pull requests, CI, review comments, issues) and chooses the single most
  valuable move and its route: finish an open pull request or build a contained
  change in the loop, or take complex work through archon-ship-block. Two independent
  reviewers then check the result: one runs the app as a user would, against the
  acceptance contract and any reviewer-only holdout scenarios, without reading
  the diff first; the other reads the diff and decides to merge it head-pinned,
  send it back with evidence, or return it to the owner. All state lives in
  GitHub, so the next run picks up where this one left off.

  Use when: a scheduler should keep a backlog moving with nobody at the
  keyboard — "keep building", "run the loop".
  NOT for: slicing a product document into issues (archon-backlog).
model: large

inputs:
  runtime:
    default: >-
      No runtime instructions were given; use what the project documents for
      running it (for example a harness or end-to-end document), if anything.
    description: >-
      How to run the app and what to look at: a path to the project''s runtime
      instructions or scenario file, or plain text. Every agent reads it.
  holdout:
    default: ""
    description: >-
      Optional path to the holdout scenarios: acceptance checks the builders
      never see. Only the holdout-verifier agent reads them, for the app check
      and the reviewer; a project can fence them inside the repository with a
      hook that refuses every other agent.
  protected_paths:
    default: ""
    description: >-
      Root-anchored path patterns only the owner may change (`*` within a
      segment, `**` across segments), comma-separated. The merge gate refuses a
      pull request that touches one. Empty or "none" protects nothing.
  merge:
    default: auto
    description: >-
      auto lets the reviewer merge what it accepts; any other value leaves the
      merge to a human after an approving comment.
  attempts:
    default: "3"
    description: >-
      How many times the loop works the same item without progress before it
      labels it needs-owner and moves on.
  rejections:
    default: "2"
    description: >-
      How many review send-backs one item may collect before the loop stops
      retrying and returns it to the owner.
  deploy:
    default: ""
    description: >-
      Optional trusted deployment command, forwarded to archon-deploy after a
      merge. Empty skips deployment.
  health:
    default: ""
    description: Trusted health command for archon-deploy; required with deploy.
  claim_hours:
    default: "6"
    description: >-
      How long a run''s claim on a work item holds when the run never releases it
      (it died). Longer than the longest lap; a run that ends releases its claim.

nodes:
  # Choose one move and how to build it. `none` is a real route, so every later
  # `when:` can read this node''s fields: it always runs.
  - id: pick
    command: loop-pick
    context: fresh
    idle_timeout: 2700000
    with:
      runtime: "$INPUTS.runtime"
      attempts: "$INPUTS.attempts"
      rejections: "$INPUTS.rejections"
      claim_hours: "$INPUTS.claim_hours"
    output_format:
      type: object
      properties:
        route: { type: string, enum: [continue, simple, complex, none] }
        target: { type: string }
        pr: { type: string }
        confidence: { type: string, enum: [high, medium, low] }
        depth: { type: string, enum: [light, normal, deep] }
        area: { type: string }
        reason: { type: string }
      required: [route, target, pr, confidence, depth, area, reason]

  # Several runs of this loop may work one repository at once. The claim is the
  # one hard fact between them: the oldest live claim comment on a work item
  # holds it, and a run that lost the race does no work this lap.
  - id: claim
    script: claim
    runtime: bun
    depends_on: [pick]
    when: "$pick.output.route != ''none''"
    with:
      target: "$pick.output.target"
      pr: "$pick.output.pr"
      route: "$pick.output.route"
      area: "$pick.output.area"
      claim_hours: "$INPUTS.claim_hours"
    output_format:
      type: object
      properties:
        held: { type: string, enum: ["true", "false"] }
        holder: { type: string }
        reason: { type: string }
      required: [held, holder, reason]

  # Contained work and finishing an open pull request: the in-loop builder.
  - id: build
    command: loop-work
    context: fresh
    idle_timeout: 2700000
    depends_on: [claim]
    when: "$claim.output.held == ''true'' && $pick.output.route == ''continue'' || $claim.output.held == ''true'' && $pick.output.route == ''simple''"
    with:
      route: "$pick.output.route"
      target: "$pick.output.target"
      pr: "$pick.output.pr"
      reason: "$pick.output.reason"
      runtime: "$INPUTS.runtime"

  # Complex work: the full shipping pipeline (triage, investigate or plan, delivery
  # rounds with review threads handled as work, CI) up to a ready pull request. The
  # building block, not the archon-ship entry: the entry pauses for a person when it
  # runs out of next steps, which would hang an unattended lap. Ordered after build
  # only so the two never run together; pick makes them exclusive.
  - id: ship
    include: archon-ship-block
    depends_on: [claim, build]
    trigger_rule: none_failed_min_one_success
    when: "$claim.output.held == ''true'' && $pick.output.route == ''complex''"
    with:
      target: "$pick.output.target"
      publish: "false"

  # What the app check tests, as facts: the pull request, its head, its base and the
  # files it changes. The builder''s report and the
  # pull request''s description are read here only to find the pull request; the app
  # check never sees them, so it tests what the change does, not what it says it does.
  - id: subject
    script: subject
    runtime: bun
    depends_on: [claim, build, ship]
    trigger_rule: all_done
    when: "$pick.output.route != ''none'' && $claim.output.held == ''true''"
    with:
      target: "$pick.output.target"
      pr: "$pick.output.pr"
      builder: { from: "$build.output", if_skipped: "" }
      ship: { from: "$ship.output", if_skipped: "" }
    output_format:
      type: object
      properties:
        pr: { type: string }
        head: { type: string }
        base: { type: string }
        files: { type: string }
        started: { type: string }
      required: [pr, head, base, files, started]

  - id: check-app
    command: loop-check-app
    context: fresh
    idle_timeout: 2700000
    depends_on: [subject]
    agents: &holdout-agents
      holdout-verifier:
        description: >-
          Runs the project''s holdout scenarios against a checkout and returns a
          verdict and what a user sees per scenario id, never the scenarios. The
          only agent allowed to read them.
        prompt: >-
          You are the holdout verifier. Before anything else, read your
          instructions in $ARTIFACTS_DIR/agents/holdout-verifier.md with your
          Read tool, and follow them exactly.
    with:
      route: "$pick.output.route"
      target: "$pick.output.target"
      pr: "$subject.output.pr"
      head: "$subject.output.head"
      base: "$subject.output.base"
      files: "$subject.output.files"
      depth: "$pick.output.depth"
      runtime: "$INPUTS.runtime"
      holdout: "$INPUTS.holdout"
    output_format:
      type: object
      properties:
        pr: { type: string }
        head: { type: string }
        merged_with: { type: string }
        lines:
          type: array
          items:
            type: object
            properties:
              id: { type: string }
              kind: { type: string, enum: [criterion, holdout, probe, defect] }
              verdict: { type: string, enum: [PASS, FAIL, INCOMPLETE, OK, SURPRISE, DEFECT, QUESTION] }
              text: { type: string }
              evidence: { type: array, items: { type: string } }
              pre_existing: { type: string }
              defect: { type: string }
              carried_from: { type: string }
            required: [id, kind, verdict, text, evidence, pre_existing, defect, carried_from]
        noticed: { type: array, items: { type: string } }
        overall: { type: string, enum: [PASS, FAIL, NO PR] }
        summary: { type: string }
      required: [pr, head, merged_with, lines, noticed, overall, summary]

  # No model: every line of the app check''s report must cite evidence written during
  # the check, every cited image must have been opened, and Overall must agree with
  # the lines. The reviewer and the merge gate both read this verdict.
  - id: evidence
    script: evidence
    runtime: bun
    depends_on: [subject, check-app]
    with:
      report: "$check-app.output"
      started: "$subject.output.started"
    output_format:
      type: object
      properties:
        ok: { type: string, enum: ["true", "false"] }
        problems: { type: string }
        overall: { type: string }
        checked_at: { type: string }
      required: [ok, problems, overall, checked_at]

  # White-box review and the merge decision. The reviewer decides; the merge gate
  # below merges, so a decision the record does not support never lands.
  - id: review
    command: loop-review
    context: fresh
    idle_timeout: 2700000
    depends_on: [check-app, evidence]
    agents: *holdout-agents
    with:
      route: "$pick.output.route"
      target: "$pick.output.target"
      pr: "$subject.output.pr"
      builder: { from: "$build.output", if_skipped: "" }
      # A complex lap that stopped short of a pull request still produced a
      # finding (its triage, plan or investigation in this run''s artifacts);
      # the reviewer posts it so the next lap starts from it.
      ship: { from: "$ship.output", if_skipped: "" }
      app_check: "$check-app.output"
      evidence_ok: "$evidence.output.ok"
      evidence_problems: "$evidence.output.problems"
      runtime: "$INPUTS.runtime"
      holdout: "$INPUTS.holdout"
      merge: "$INPUTS.merge"
      rejections: "$INPUTS.rejections"
    output_format:
      type: object
      properties:
        outcome: { type: string, enum: [merge, sent-back, needs-owner, approved, nothing] }
        pr: { type: string }
        sha: { type: string }
        delivers: { type: string, enum: [all, part, none] }
        dispositions:
          type: array
          items:
            type: object
            properties:
              line: { type: string }
              action: { type: string, enum: [blocks, rechecked, pre-existing, issue, accepted] }
              file: { type: string }
              issue: { type: string }
              reason: { type: string }
            required: [line, action, file, issue, reason]
        judge_changes:
          type: array
          items:
            type: object
            properties:
              file: { type: string }
              change: { type: string }
              approval: { type: string }
            required: [file, change, approval]
        reason: { type: string }
      required: [outcome, pr, sha, delivers, dispositions, judge_changes, reason]

  # The merge gate (no model). Merges the reviewed commit only when the evidence held,
  # every failing line has the reviewer''s re-check or default-branch proof, every
  # pre-existing failure and question is tracked or decided, no shipping node failed,
  # and the commit contains the current default branch. Otherwise it says why.
  - id: land
    script: land
    runtime: bun
    depends_on: [subject, check-app, evidence, review]
    when: "$review.output.outcome == ''merge'' && $INPUTS.merge == ''auto''"
    with:
      pr: "$review.output.pr"
      sha: "$review.output.sha"
      delivers: "$review.output.delivers"
      dispositions: "$review.output.dispositions"
      judge_changes: "$review.output.judge_changes"
      route: "$pick.output.route"
      target: "$pick.output.target"
      report: "$check-app.output"
      evidence_problems: "$evidence.output.problems"
      review_started: "$evidence.output.checked_at"
      files: "$subject.output.files"
      protected_paths: "$INPUTS.protected_paths"
    output_format:
      type: object
      properties:
        outcome: { type: string, enum: [merged, refused] }
        reason: { type: string }
      required: [outcome, reason]

  # Merging is not shipping: with a deploy command set, roll the merge out and
  # read the revision back.
  - id: deploy
    include: archon-deploy
    depends_on: [land]
    when: "$land.output.outcome == ''merged'' && $INPUTS.deploy != ''''"
    with:
      deploy: "$INPUTS.deploy"
      health: "$INPUTS.health"
      identity: ""

  # Free the work item for the next lap however this run ended: after review and
  # deploy finished, failed or were skipped.
  - id: release
    script: release
    runtime: bun
    depends_on: [claim, review, land, deploy]
    trigger_rule: all_done
    when: "$pick.output.route != ''none'' && $claim.output.held == ''true''"
    with:
      target: "$pick.output.target"
      pr: "$pick.output.pr"

  # Count the lap in the factory''s own log once the work item is free.
  - id: tally
    bash: "echo lap done"
    depends_on: [release]
    trigger_rule: all_done
');
INSERT INTO mc.arch_workflows (archon_sha, factory_sha, name, description, model, file, yaml) VALUES ('2b7c4e9a1f0d3c5b6a7e8f9d0c1b2a3f4e5d6c7b', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-manager', 'Step back from the ticket loop and steer it. One agent looks at the whole
system (issues, pull requests, what merged, CI, the product itself) and fixes
what a single ticket cannot see: duplicates, impossible criteria, stuck or
orphaned work, recurring causes that need one redesign instead of more
patches, defects that got past review, and the order of work. Owner
questions go into one issue with a stated default; one metrics line per pass.

Use when: on a slower schedule than archon-loop (every few hours), or when the
loop stops making progress.
NOT for: writing product code.
', 'large', 'manager/archon-manager.yaml', 'name: archon-manager
description: |
  Step back from the ticket loop and steer it. One agent looks at the whole
  system (issues, pull requests, what merged, CI, the product itself) and fixes
  what a single ticket cannot see: duplicates, impossible criteria, stuck or
  orphaned work, recurring causes that need one redesign instead of more
  patches, defects that got past review, and the order of work. Owner
  questions go into one issue with a stated default; one metrics line per pass.

  Use when: on a slower schedule than archon-loop (every few hours), or when the
  loop stops making progress.
  NOT for: writing product code.
model: large

inputs:
  runtime:
    default: >-
      No runtime instructions were given; use what the project documents for
      running it (for example a harness or end-to-end document), if anything.
    description: >-
      How to run the app and what to look at: a path to the project''s runtime
      instructions or scenario file, or plain text.
  holdout:
    default: ""
    description: >-
      Optional path to the holdout scenarios. The manager runs them on the
      default branch through the holdout-verifier agent and adds scenarios
      through the holdout-writer agent (for each defect that got past review,
      and before a new section of the product is built); it never reads them
      itself.

nodes:
  # The holdout agents'' instructions are command files in this pack; an inline agent cannot
  # reach the pack, so this copies them where the agents'' prompts point.
  - id: briefs
    script: briefs
    runtime: bun

  - id: manage
    command: manage
    context: fresh
    idle_timeout: 2700000
    depends_on: [briefs]
    agents:
      holdout-verifier:
        description: >-
          Runs the project''s holdout scenarios against a checkout and returns a
          verdict and what a user sees per scenario id, never the scenarios. The
          only agent, with holdout-writer, allowed to read them.
        prompt: >-
          You are the holdout verifier. Before anything else, read your
          instructions in $ARTIFACTS_DIR/agents/holdout-verifier.md with your
          Read tool, and follow them exactly.
      holdout-writer:
        description: >-
          Writes the project''s holdout scenarios from the product
          document or an escaped defect, commits them, and returns one line per
          scenario id. The only agent, with holdout-verifier, allowed to read them.
        prompt: >-
          You are the holdout writer. Before anything else, read your
          instructions in $ARTIFACTS_DIR/agents/holdout-writer.md with your Read
          tool, and follow them exactly.
    with:
      runtime: "$INPUTS.runtime"
      holdout: "$INPUTS.holdout"
');
