INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/deliver/rounds/rereview/route', 'ship/deliver/rounds/rereview', 52, 'route', 'command', 'After scope checks the head, a small model reads the diff
summary and the work order and answers, with seams on by default. Every round
but a light one routes; on a continuation route adds to the code lens every lens
whose finding the previous report leaves open or whose area the delta touches.', 'small', '$scope.output.head_matches == true && $mode.output.light == false', ARRAY['mode', 'scope']::text[], NULL, NULL, NULL, NULL, 'route-review', 'review/commands/route-review.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/deliver/rounds/rereview/seams', 'ship/deliver/rounds/rereview', 53, 'seams', 'command', '── Lenses ────────────────────────────────────────────────────────
Every reviewer is read-only by the engine''s check, not only by its prompt:
lenses run in parallel in one checkout, so a reviewer that edits it can
mislead the others. `&&` binds tighter than `||` and short-circuits, so a
light round, which skips the route node, never reads it.', '@review-seams @reviewer medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.seams == true || $scope.output.head_matches == true && $mode.output.seams == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-seams', 'review/commands/review-seams.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/deliver/rounds/rereview/code', 'ship/deliver/rounds/rereview', 54, 'code', 'command', NULL, '@review-code @reviewer large', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.code == true || $scope.output.head_matches == true && $mode.output.code == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-code', 'review/commands/review-code.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/deliver/rounds/rereview/tests', 'ship/deliver/rounds/rereview', 55, 'tests', 'command', NULL, '@review-tests @reviewer medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.tests == true || $scope.output.head_matches == true && $mode.output.tests == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-tests', 'review/commands/review-tests.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/deliver/rounds/rereview/errors', 'ship/deliver/rounds/rereview', 56, 'errors', 'command', NULL, '@review-errors @reviewer medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.errors == true || $scope.output.head_matches == true && $mode.output.errors == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-errors', 'review/commands/review-errors.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/deliver/rounds/rereview/docs', 'ship/deliver/rounds/rereview', 57, 'docs', 'command', NULL, '@review-docs @reviewer medium', '$scope.output.head_matches == true && $mode.output.light == false && $route.output.docs == true || $scope.output.head_matches == true && $mode.output.docs == true', ARRAY['scope', 'route']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'review-docs', 'review/commands/review-docs.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/deliver/rounds/rereview/review-complete', 'ship/deliver/rounds/rereview', 58, 'review-complete', 'bash', 'all_done lets this barrier settle after unselected lenses, or a lens whose
retries were exhausted. The deciding
agent can then tolerate specialist failures without also tolerating a failed
mode/scope preflight: synthesize separately requires both to have succeeded.', NULL, '$scope.output.head_matches == true', ARRAY['scope', 'route', 'seams', 'code', 'tests', 'errors', 'docs']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'true', NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/deliver/rounds/rereview/synthesize', 'ship/deliver/rounds/rereview', 59, 'synthesize', 'command', 'A failed specialist (a provider stream dying mid-review, say) must not kill
the review: synthesize detects the missing completion for a selected lens and
forces ready:false naming the gap, so degradation is disclosed, never silent,
and the next round is the retry. `ready` is a real boolean — the load-bearing field a composing
loop terminates on. Every round receives this round''s lens files; a
continuation also receives the complete prior report and correction delta.

The deciding agent and the lenses start fresh and carry earlier rounds through
the prior report, not a resumed session: a loop body cannot resume a session
from its own earlier iteration, and session resume is not portable across the
bundle''s supported providers (Claude Code, Codex, and Pi).

Adversarial per-finding verification happens inside this node''s prompt. A
separate verify stage between the lenses and this node is now expressible and
would not change either side''s contract — the findings files are the declared
boundary — but nothing has measured it as better than the in-prompt pass, so
it stays here until something does.', '@reviewer medium', '$scope.output.head_matches == true', ARRAY['policy', 'mode', 'scope', 'review-complete']::text[], NULL, NULL, NULL, NULL, 'review-synthesize', 'review/commands/review-synthesize.md', NULL, NULL, NULL, NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/deliver/rounds/rereview/publish', 'ship/deliver/rounds/rereview', 60, 'publish', 'script', 'The reviewer judges and writes the report; this node owns the one public
write, so every round edits the same marked comment instead of appending
another, through whichever forge source the run selected (on `gh`, a landed
write that returned a retryable response (5xx, or a rate limit) or no response can leave a second one, and the next
upsert refuses). The verdict passes
through unchanged: publication is not what makes a review true.', NULL, '$scope.output.head_matches == true', ARRAY['synthesize']::text[], NULL, NULL, NULL, NULL, NULL, NULL, 'publish-review', 'review/scripts/publish-review.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/deliver/rounds/rereview/result', 'ship/deliver/rounds/rereview', 61, 'result', 'script', 'Standalone runs show the first completed sink, so the verdict precedes cleanup.', NULL, NULL, ARRAY['scope', 'publish']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, NULL, NULL, 'const verdict = JSON.parse(process.env.INPUTS_VERDICT);
const report = JSON.parse(process.env.INPUTS_SCOPE_REPORT);
console.log(JSON.stringify(JSON.parse(process.env.INPUTS_HEAD_MATCHES) ? verdict : {
  ready: false, action: "ask",
  findings_summary: require("node:fs").readFileSync(require("node:path").join(process.env.ARTIFACTS_DIR, report.path), "utf8"),
  report, discoveries: [], contract_left: ["PR head mismatch prevented contract review."]
}));
', NULL, 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/deliver/rounds/rereview/prune-scratch', 'ship/deliver/rounds/rereview', 62, 'prune-scratch', 'script', 'Reviewers'' scratch worktrees are removed by the workflow once every lens and
the deciding agent have settled, whether they succeeded or failed.', NULL, NULL, ARRAY['synthesize']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, 'prune-scratch', 'review/scripts/prune-scratch.ts', 'bun', NULL, NULL, 'archon-review-block', 'review/archon-review-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/deliver/rounds/settle-threads', 'ship/deliver/rounds', 63, 'settle-threads', 'command', 'Review threads are work too, whoever opened them. This round''s implementer
judged the threads the previous round read; this agent checks each
disposition at the head and writes the reply each settled thread gets.', 'medium', '$LOOP_PREV.threads.output.open > 0', ARRAY['pr', 'review', 'rereview']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'settle-threads', 'deliver/commands/settle-threads.md', NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/deliver/rounds/ci', 'ship/deliver/rounds', 64, 'ci', 'command', 'CI is the project''s full validation: implementers run only focused checks.
Fresh: CI reads the PR, not simplify''s or reshape''s conversation.', 'medium', '$review.output.ready == true && $simplify.output.findings == false || $review.output.ready == true && $simplify.output.findings == true && $rereview.output.ready == true', ARRAY['review', 'simplify', 'rereview', 'settle-threads']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'ci', 'deliver/commands/ci.md', NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/deliver/rounds/threads', 'ship/deliver/rounds', 65, 'threads', 'script', 'Posts and resolves settle-threads'' answers, then reads what is still open,
after CI so threads posted during the round count.', NULL, NULL, ARRAY['pr', 'review', 'rereview', 'ci', 'settle-threads']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, NULL, NULL, 'threads', 'deliver/scripts/threads.ts', 'bun', NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/deliver/rounds/round', 'ship/deliver/rounds', 66, 'round', 'script', '`until_bash` and the loop''s output cannot read a skipped node, so this joins
the round''s verdicts into the value the loop decides on.', NULL, NULL, ARRAY['implement', 'pr', 'review', 'rereview', 'ci', 'threads']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, 'round', 'deliver/scripts/round.ts', 'bun', NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/deliver/update-pr-body', 'ship/deliver', 67, 'update-pr-body', 'command', 'Corrections and the base merge can falsify claims the description made when the
draft opened, and an implementer can pass red the description must disclose. One
agent reads the live description and the final diff, and edits only what is no
longer true. It also links the issue: closing only when the latest review left
nothing open and no dated ruling on the issue keeps it open. It runs once the
rounds have ended, never per round;
content a round prepared for the description is that round''s pr step''s write.', 'medium', '$rounds.output.pr_url != ''''', ARRAY['rounds']::text[], NULL, NULL, NULL, NULL, 'update-pr-body', 'deliver/commands/update-pr-body.md', NULL, NULL, NULL, NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/deliver/outcome', 'ship/deliver', 68, 'outcome', 'script', 'Composes the success-path report (scripts/outcome.ts): ready with the pull
request''s URL, or not ready with why. `report` relays it.', NULL, NULL, ARRAY['rounds', 'update-pr-body']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, NULL, NULL, 'outcome', 'deliver/scripts/outcome.ts', 'bun', NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/deliver/report', 'ship/deliver', 69, 'report', 'script', 'The workflow''s terminal report on every ending. A node failure skips `outcome`
(never fails it), so `all_done` still runs this node and the binding reads null.
`always_run` because it reads discoveries its dependency edge does not carry.', NULL, NULL, ARRAY['outcome']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, 'report', 'deliver/scripts/report.ts', 'bun', NULL, NULL, 'archon-deliver-block', 'deliver/archon-deliver-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/outcome', 'ship', 70, 'outcome', 'script', 'The result of every legitimate ending, relayed by `report`. Negative advisory verdicts
complete with the report that explains them; a delivery is reported from the
deliver branch''s own outcome, ready or not (bound with if_skipped, so a skipped
branch arrives as null) — see scripts/outcome.ts.

The advisory producers are bound with if_skipped: a route that never ran them
reads null. Two dependencies carry the whole graph. `deliver` depends on triage,
inv and planned, so nothing this node reports on can settle after it. `triage` is named because
none_failed_min_one_success needs one completed dependency, and on the no_action
route `deliver` is the skipped one.

A failed delivery reaches this node through deliver''s report (`reason: failed`
or `pr_create_unresolved`) and is relayed like any other not-ready delivery. A
failure before delivery skips this node, and `report` answers.', NULL, NULL, ARRAY['triage', 'deliver']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, NULL, NULL, 'outcome', 'ship/scripts/outcome.ts', 'bun', NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'ship/report', 'ship', 71, 'report', 'script', 'The workflow''s terminal report on every ending. A node failure skips `outcome`
(never fails it), so `all_done` still runs this node and the binding reads null.
`always_run` because it reads discoveries its dependency edge does not carry.', NULL, NULL, ARRAY['outcome']::text[], 'all_done', NULL, NULL, NULL, NULL, NULL, 'report', 'ship/scripts/report.ts', 'bun', NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'answer', NULL, 72, 'answer', 'command', NULL, 'large', '$facts.output.path == ''route'' && $route.output.decision == ''launch''', ARRAY['facts', 'checkout', 'ship']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, 'answer', 'build-queue/commands/answer.md', NULL, NULL, NULL, NULL, NULL, 'archon-build-queue', 'build-queue/archon-build-queue.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-build-queue', 'apply', NULL, 73, 'apply', 'script', 'Checks the decision, performs the writes it declared and reads each one back:
the push, then the work item.', NULL, NULL, ARRAY['facts', 'route', 'answer']::text[], 'none_failed_min_one_success', NULL, NULL, NULL, NULL, NULL, 'apply', 'build-queue/scripts/apply.ts', 'bun', NULL, NULL, 'archon-build-queue', 'build-queue/archon-build-queue.yaml');
