INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'triage', NULL, 1, 'triage', 'include', 'The source is history, not a work order. Triage checks it against current
code and direction before deciding which kind of reasoning is still owed.', NULL, NULL, ARRAY['forge']::text[], NULL, 'archon-triage-block', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'archon-ship-block', 'ship/archon-ship-block.yaml');
INSERT INTO mc.arch_steps (archon_sha, factory_sha, workflow, path, parent_path, position, step_id, kind, description, model, when_condition, depends_on, trigger_rule, include, child_workflow, round_cap, command, command_file, script, script_file, runtime, bash, prompt, defined_in, file) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', 'archon-ship-block', 'triage/policy', 'triage', 2, 'policy', 'script', 'The directory of the pack''s default policy documents in this run''s captured
