INSERT INTO mc.arch_scripts (archon_sha, factory_sha, path, text) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '.archon/workflows/factory/app-check/scripts/binding.ts', 'import { createHash } from "node:crypto";

export interface CommitStatus { context: string; state: string; description?: string | null; created_at?: string }
export const PENDING_MAX_AGE_MS = 2 * 60 * 60 * 1000;
const NOT_ABOUT_THE_CODE = /did not complete|stale:/;

export function appCheckBinding(base: string, baseOid: string): string {
  return createHash("sha256").update(`${base}\0${baseOid}`).digest("hex");
}

export function boundDescription(base: string, baseOid: string, message: string): string {
  return `binding=${appCheckBinding(base, baseOid)}; ${message}`;
}

/**
 * A result belongs to the pull request''s commit. A pass or a failure stands until a new commit
 * arrives, so a merge to the base no longer voids every open check. Results the check itself says
 * are not about the code (it never finished) do not count, so the scheduler runs them again.
 */
export function statusJudgesHead(statuses: CommitStatus[], now = Date.now()): boolean {
  const latest = statuses.find(status => status.context === "factory/app-check");
  if (!latest) return false;
  if (latest.state === "success") return true;
  if (latest.state === "failure") return !NOT_ABOUT_THE_CODE.test(latest.description ?? "");
  if (latest.state !== "pending") return false;
  const created = Date.parse(latest.created_at ?? "");
  return Number.isFinite(created) && now - created <= PENDING_MAX_AGE_MS;
}
');
INSERT INTO mc.arch_scripts (archon_sha, factory_sha, path, text) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '.archon/workflows/factory/app-check/scripts/cleanup.ts', 'import { existsSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawnSync } from "node:child_process";
import { env, jsonEnv, run } from "../../.shared/utils.ts";
import { appProcessRecordPath, stopRecordedApp } from "./app-process.ts";

const tempFile = process.env.ARTIFACTS_DIR ? join(process.env.ARTIFACTS_DIR, "app-check", "temp-path.txt") : "";
const temp = env("temp") || (tempFile && existsSync(tempFile) ? readFileSync(tempFile, "utf8").trim() : "");
const appRecord = process.env.ARTIFACTS_DIR ? appProcessRecordPath() : "";
const appCleanup = appRecord ? stopRecordedApp(appRecord) : { status: "no-record" as const };
// A runtime-mode app is stopped by the owner''s teardown, run from the checkout that started it.
const teardown = (jsonEnv<{ app?: { teardown?: string } }>("config", {}).app?.teardown ?? "").trim();
const teardownStatus = teardown && temp && existsSync(temp)
  ? (spawnSync("bash", ["-c", teardown], { cwd: temp, stdio: "ignore", timeout: 120_000 }).status === 0 ? "ok" : "failed")
  : "none";
if (temp) {
  run(["git", "worktree", "remove", "--force", temp], { allowFailure: true });
  const safePrefix = join(tmpdir(), "factory-app-check-").toLowerCase();
  if (existsSync(temp) && temp.toLowerCase().startsWith(safePrefix)) rmSync(temp, { recursive: true, force: true });
}
console.log(JSON.stringify({ cleaned: Boolean(temp), app_record: Boolean(appRecord && existsSync(appRecord)), app_cleanup: appCleanup.status, teardown: teardownStatus }));
');
INSERT INTO mc.arch_scripts (archon_sha, factory_sha, path, text) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '.archon/workflows/factory/app-check/scripts/config.ts', 'import { readFactoryConfig } from "../../../../scripts/factory-config.ts";
console.log(JSON.stringify(readFactoryConfig()));
');
INSERT INTO mc.arch_scripts (archon_sha, factory_sha, path, text) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '.archon/workflows/factory/app-check/scripts/evidence.ts', 'import { existsSync, readFileSync, statSync } from "node:fs";
import { isAbsolute, join, resolve } from "node:path";
import { emit, env, readJsonFile } from "../../.shared/utils.ts";

export const LINE = /^(C\d+|P\d+|A\d+)\s{2}(PASS|FAIL|INCOMPLETE)\s{2}(.+?)\s{2}evidence:\s+(.+)$/;
export function evidenceProblems(result: any, report: string, root: string, preparedAt: number): string[] {
  const problems: string[] = [], lines = Array.isArray(result?.lines) ? result.lines : [];
  if (!lines.length) problems.push("result has no check lines");
  let blocked = false, criteria = 0;
  const seen = new Set<string>();
  for (const raw of lines) {
    const match = typeof raw === "string" ? raw.match(LINE) : null;
    if (!match) { problems.push(`invalid line: ${String(raw)}`); continue; }
    const id = match[1]!;
    if (seen.has(id)) problems.push(`duplicate check id: ${id}`);
    seen.add(id);
    if (id.startsWith("C")) criteria++;
    if (match[2] !== "PASS") blocked = true;
    const cited = match[4]!.trim();
    const path = isAbsolute(cited) ? cited : resolve(root, cited);
    if (!existsSync(path) || !statSync(path).isFile()) problems.push(`${match[1]} cites a missing file: ${cited}`);
    else if (statSync(path).mtimeMs < preparedAt) problems.push(`${match[1]} cites evidence older than prepare: ${cited}`);
    if (!report.includes(raw)) problems.push(`${match[1]} is absent from report.md`);
  }
  if (criteria === 0) problems.push("result has no acceptance/core check lines");
  const expectedOverall = blocked ? "FAIL" : "PASS";
  if (result?.overall !== expectedOverall) problems.push(`overall must be ${expectedOverall}`);
  return problems;
}

if (import.meta.main) {
  const root = join(process.env.ARTIFACTS_DIR!, "app-check"), resultPath = join(root, "result.json"), reportPath = join(root, "report.md");
  if (!existsSync(resultPath) || !existsSync(reportPath)) throw new Error("check must write app-check/result.json and app-check/report.md");
  const preparedAt = Number(env("prepared_at"));
  if (statSync(resultPath).mtimeMs < preparedAt || statSync(reportPath).mtimeMs < preparedAt) throw new Error("result.json and report.md must be written after prepare");
  const result = readJsonFile<any>(resultPath), report = readFileSync(reportPath, "utf8");
  const problems = evidenceProblems(result, report, root, preparedAt);
  if (problems.length) throw new Error(problems.join("\n"));
  emit({ overall: result.overall, lines: result.lines, report });
}
');
INSERT INTO mc.arch_scripts (archon_sha, factory_sha, path, text) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '.archon/workflows/factory/app-check/scripts/finalize.ts', 'import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { boundDescription } from "./binding.ts";
import { emit, postStatus } from "../../.shared/utils.ts";

interface PendingRecord { repo: string; head: string; base: string; base_oid: string }
type StatusWriter = (repo: string, head: string, state: "pending" | "success" | "failure", context: string, description: string) => void;

export function finalizePending(root: string, writeStatus: StatusWriter = postStatus): boolean {
  const pendingPath = join(root, "pending.json"), terminalPath = join(root, "terminal.json");
  if (existsSync(terminalPath) || !existsSync(pendingPath)) return false;
  const pending = JSON.parse(readFileSync(pendingPath, "utf8")) as PendingRecord;
  writeStatus(pending.repo, pending.head, "failure", "factory/app-check", boundDescription(pending.base, pending.base_oid, "app check did not complete"));
  mkdirSync(root, { recursive: true });
  writeFileSync(terminalPath, JSON.stringify({ state: "failure", reason: "incomplete" }));
  return true;
}

if (import.meta.main) {
  emit({ recovered: finalizePending(join(process.env.ARTIFACTS_DIR!, "app-check")) });
}
');
INSERT INTO mc.arch_scripts (archon_sha, factory_sha, path, text) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '.archon/workflows/factory/app-check/scripts/pending.ts', 'import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { boundDescription } from "./binding.ts";
import { env, postStatus } from "../../.shared/utils.ts";
const repo = env("repo_path"), head = env("head"), base = env("base"), baseOid = env("base_oid");
postStatus(repo, head, "pending", "factory/app-check", boundDescription(base, baseOid, "black-box app check running"));
const root = join(process.env.ARTIFACTS_DIR!, "app-check");
mkdirSync(root, { recursive: true });
writeFileSync(join(root, "pending.json"), JSON.stringify({ repo, head, base, base_oid: baseOid }));
console.log(JSON.stringify({ posted: true }));
');
INSERT INTO mc.arch_scripts (archon_sha, factory_sha, path, text) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '.archon/workflows/factory/app-check/scripts/policy.ts', 'import type { FactoryConfig } from "../../../../scripts/factory-config.ts";
import { emit, env, jsonEnv, matchingFiles, postStatus } from "../../.shared/utils.ts";

interface ProtectedGrant { head: string; paths: string[] }
export function protectedGrantAllows(raw: string, head: string, paths: string[]): boolean {
  if (!raw || paths.length === 0) return false;
  let grant: ProtectedGrant;
  try { grant = JSON.parse(raw) as ProtectedGrant; } catch { return false; }
  if (!grant || typeof grant !== "object" || grant.head !== head || !Array.isArray(grant.paths) || grant.paths.some(path => typeof path !== "string")) return false;
  if (Object.keys(grant).sort().join(",") !== "head,paths") return false;
  const requested = [...new Set(paths)].sort(), granted = [...new Set(grant.paths)].sort();
  return grant.paths.length === granted.length && requested.length === granted.length && requested.every((path, index) => path === granted[index]);
}

if (import.meta.main) {
  const config = jsonEnv<FactoryConfig>("config", {} as FactoryConfig), files = jsonEnv<string[]>("files", []);
  const protectedFiles = matchingFiles(files, config.protected_paths);
  const ok = protectedFiles.length === 0 || protectedGrantAllows(env("grant"), env("head"), protectedFiles);
  const description = ok ? "policy clear" : "protected path: needs an owner ruling";
  postStatus(env("repo_path"), env("head"), ok ? "success" : "failure", "factory/policy", description);
  emit({ ok, protected_files: protectedFiles, description });
}
');
INSERT INTO mc.arch_scripts (archon_sha, factory_sha, path, text) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '.archon/workflows/factory/app-check/scripts/prepare.ts', 'import { mkdirSync, mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { emit, env, run } from "../../.shared/utils.ts";

const base = env("base"), baseOid = env("base_oid"), head = env("head"), pr = env("pr");
const temp = mkdtempSync(join(tmpdir(), "factory-app-check-"));
const artifactRoot = join(process.env.ARTIFACTS_DIR!, "app-check");
mkdirSync(artifactRoot, { recursive: true });
writeFileSync(join(artifactRoot, "temp-path.txt"), temp);
const headRef = `refs/factory/app-check-${pr}`;
// Fetch the head by the commit select chose, not through refs/pull/<pr>/head: GitHub updates that mirror
// asynchronously and it can stay on an older commit (2026-11-09, Mission Control PR 542, through a close and
// reopen). The status is bound to this commit anyway.
run(["git", "fetch", "origin", `+refs/heads/${base}:refs/remotes/origin/${base}`, `+${head}:${headRef}`]);
const fetchedBase = run(["git", "rev-parse", `refs/remotes/origin/${base}`]);
const fetchedHead = run(["git", "rev-parse", headRef]);
if (fetchedBase !== baseOid || fetchedHead !== head) throw new Error("pull request head/base changed before preparation");
run(["git", "worktree", "add", "--detach", temp, fetchedBase]);
run(["git", "merge", "--no-edit", fetchedHead], { cwd: temp });
emit({ temp, merged: run(["git", "rev-parse", "HEAD"], { cwd: temp }), prepared_at: Date.now() });
');
INSERT INTO mc.arch_scripts (archon_sha, factory_sha, path, text) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '.archon/workflows/factory/app-check/scripts/publish.ts', 'import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { boundDescription } from "./binding.ts";
import { env, ghJson, jsonEnv, postStatus, run } from "../../.shared/utils.ts";

interface CurrentPull { state: string; headRefOid: string; baseRefName: string }
/** The base may have moved during the check: a result belongs to the commit it tested. */
export function resultIsCurrent(current: CurrentPull, head: string, base: string): boolean {
  return current.state === "OPEN" && current.headRefOid === head && current.baseRefName === base;
}

if (import.meta.main) {
  const repo = env("repo_path"), head = env("head"), base = env("base"), baseOid = env("base_oid"), pr = env("pr"), overall = env("overall");
  const lines = jsonEnv<string[]>("lines", []);
  const current = ghJson(["pr", "view", pr, "--repo", repo, "--json", "state,headRefOid,baseRefName"]) as CurrentPull;
  const fresh = resultIsCurrent(current, head, base);
  const state = overall === "PASS" && fresh ? "success" : "failure";
  const message = !fresh ? "stale: pull request head changed" : overall === "PASS" ? "black-box app check passed" : "black-box app check failed";
  postStatus(repo, head, state, "factory/app-check", boundDescription(base, baseOid, message));
  const marker = "<!-- factory-app-check -->";
  const freshness = `Tested head \`${head}\` against \`${base}\` at \`${baseOid}\`.${fresh ? "" : " The pull request changed before publication; this result is a failure."}`;
  const body = `${marker}\n## Factory app check: ${state === "success" ? "PASS" : "FAIL"}\n\n${freshness}\n\n${lines.join("\n")}`;
  const comments = ghJson(["api", `repos/${repo}/issues/${pr}/comments`, "--paginate"]) as { id: number; body: string }[];
  const prior = comments.find(comment => comment.body.includes(marker));
  const root = join(process.env.ARTIFACTS_DIR!, "app-check"), file = join(root, "comment.json");
  await Bun.write(file, JSON.stringify({ body }));
  if (prior) run(["gh", "api", "--method", "PATCH", `repos/${repo}/issues/comments/${prior.id}`, "--input", file]);
  else run(["gh", "api", "--method", "POST", `repos/${repo}/issues/${pr}/comments`, "--input", file]);
  mkdirSync(root, { recursive: true });
  writeFileSync(join(root, "terminal.json"), JSON.stringify({ state, fresh }));
  console.log(JSON.stringify({ state, comment: prior ? "updated" : "created" }));
}
');
INSERT INTO mc.arch_scripts (archon_sha, factory_sha, path, text) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '.archon/workflows/factory/app-check/scripts/scope.ts', 'import type { FactoryConfig } from "../../../../scripts/factory-config.ts";
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { boundDescription } from "./binding.ts";
import { emit, env, jsonEnv, matchingFiles, postStatus } from "../../.shared/utils.ts";

export function scopeDecision(config: FactoryConfig, files: string[], labels: string[]) {
  const depth = config.app_check.depth === "auto"
    ? labels.includes("archon-size-l") ? "deep" : labels.includes("archon-size-s") ? "light" : "normal"
    : config.app_check.depth;
  if (!config.app_check.enabled || config.app_check.trigger === "never") return { run: false, depth, reason: "skipped: app check disabled" };
  if (config.app_check.trigger === "frontend" && matchingFiles(files, config.app_check.frontend_paths).length === 0)
    return { run: false, depth, reason: "skipped: no front-end change" };
  return { run: true, depth, reason: "selected" };
}

if (import.meta.main) {
  const decision = scopeDecision(jsonEnv<FactoryConfig>("config", {} as FactoryConfig), jsonEnv("files", []), jsonEnv("labels", []));
  if (!decision.run) {
    postStatus(env("repo_path"), env("head"), "success", "factory/app-check", boundDescription(env("base"), env("base_oid"), decision.reason));
    const root = join(process.env.ARTIFACTS_DIR!, "app-check");
    mkdirSync(root, { recursive: true });
    writeFileSync(join(root, "terminal.json"), JSON.stringify({ state: "success", reason: decision.reason }));
  }
  emit(decision);
}
');
INSERT INTO mc.arch_scripts (archon_sha, factory_sha, path, text) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '.archon/workflows/factory/app-check/scripts/select.ts', 'import { emit, env, ghJson, linkedIssue } from "../../.shared/utils.ts";
import { currentBranchOid } from "./base.ts";
import { statusJudgesHead, type CommitStatus } from "./binding.ts";

export interface Candidate { number: number; isDraft: boolean; createdAt: string; headRefOid: string; baseRefName: string; baseRefOid: string; files: { path: string }[]; body: string; state?: string; mergeable?: string }
type PullCandidate = Omit<Candidate, "baseRefOid"> & { baseRefOid?: string };
export function oldestUnchecked(rows: Candidate[], judgedHeads: Set<string>): Candidate | null {
  // A conflicting pull request cannot be merged with its base for testing; checking it first would starve every newer one.
  return rows.filter(row => (!row.state || row.state === "OPEN") && row.mergeable !== "CONFLICTING" && !judgedHeads.has(row.headRefOid)).sort((a, b) => a.createdAt.localeCompare(b.createdAt))[0] ?? null;
}

function hasResult(repo: string, row: Candidate): boolean {
  const statuses = ghJson(["api", `repos/${repo}/commits/${row.headRefOid}/statuses`]) as CommitStatus[];
  return statusJudgesHead(statuses);
}

if (import.meta.main) {
  const repo = env("repo_path"), requested = env("pr");
  const fields = "number,isDraft,createdAt,headRefOid,baseRefName,baseRefOid,files,body,state,mergeable";
  const pullRows = requested
    ? [ghJson(["pr", "view", requested, "--repo", repo, "--json", fields]) as PullCandidate]
    : ghJson(["pr", "list", "--repo", repo, "--state", "open", "--limit", "100", "--json", fields]) as PullCandidate[];
  const baseTips = new Map<string, string>();
  const rows = pullRows.map(row => {
    const baseRefOid = baseTips.get(row.baseRefName) ?? currentBranchOid(repo, row.baseRefName);
    baseTips.set(row.baseRefName, baseRefOid);
    return { ...row, baseRefOid } as Candidate;
  });
  const judged = new Set(requested ? [] : rows.filter(row => hasResult(repo, row)).map(row => row.headRefOid));
  const picked = requested ? (rows[0]?.state === "OPEN" ? rows[0] : null) : oldestUnchecked(rows, judged);
  if (!picked) emit({ found: false, pr: null, head: "", files: [], base: "", base_oid: "", issue: null, issue_body: "", issue_labels: [] });
  else {
    const issue = linkedIssue(picked.body);
    const detail = issue ? ghJson(["issue", "view", String(issue), "--repo", repo, "--json", "body,labels"]) : null;
    emit({ found: true, pr: picked.number, head: picked.headRefOid, files: picked.files.map(file => file.path), base: picked.baseRefName, base_oid: picked.baseRefOid, issue,
      issue_body: detail?.body ?? "", issue_labels: (detail?.labels ?? []).map((label: { name: string }) => label.name) });
  }
}
');
INSERT INTO mc.arch_scripts (archon_sha, factory_sha, path, text) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '.archon/workflows/factory/backlog/scripts/check.ts', 'import { emit, readJsonFile } from "../../.shared/utils.ts";

const REQUIRED = ["Problem", "Why", "Why now", "Outcome", "Invariants", "Acceptance"];
export function validateBacklog(value: unknown): string[] {
  const errors: string[] = [];
  if (!Array.isArray(value)) return ["backlog.json must be an array"];
  if (value.length > 12) errors.push("backlog exceeds 12 tickets");
  const seen = new Set<string>();
  value.forEach((raw, index) => {
    const ticket = raw as any, key = ticket?.key;
    if (typeof key !== "string" || !/^[a-z0-9][a-z0-9-]{1,60}$/.test(key)) errors.push(`ticket ${index + 1} has an invalid key`);
    else if (seen.has(key)) errors.push(`duplicate key ${key}`);
    if (typeof ticket?.title !== "string" || !ticket.title.trim()) errors.push(`${key ?? index + 1} needs a title`);
    if (typeof ticket?.body !== "string") errors.push(`${key ?? index + 1} needs a body`);
    else {
      for (const heading of REQUIRED) if (!new RegExp(`^## ${heading}\\s*$`, "mi").test(ticket.body)) errors.push(`${key} lacks ${heading}`);
      if (!ticket.body.includes(`<!-- factory-backlog: ${key} -->`)) errors.push(`${key} lacks its dedup marker`);
      if (!/^\s*- \[[ xX]\]/m.test(ticket.body.split(/^## Acceptance\s*$/mi)[1] ?? "")) errors.push(`${key} acceptance is not a checklist`);
    }
    const deps = ticket?.depends_on;
    if (!Array.isArray(deps) || deps.some((dep: unknown) => typeof dep !== "string" || !seen.has(dep))) errors.push(`${key} dependencies must name earlier tickets`);
    if (index === 0 && deps?.length) errors.push("first ticket must have no dependencies");
    if (!["s", "m", "l"].includes(ticket?.size)) errors.push(`${key} size must be s, m, or l`);
    if (typeof key === "string") seen.add(key);
  });
  return errors;
}

if (import.meta.main) {
  const tickets = readJsonFile<any[]>(`${process.env.ARTIFACTS_DIR}/backlog.json`);
  const errors = validateBacklog(tickets); if (errors.length) throw new Error(errors.join("\n"));
  emit({ count: tickets.length, keys: tickets.map((ticket: any) => ticket.key) });
}
');
INSERT INTO mc.arch_scripts (archon_sha, factory_sha, path, text) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '.archon/workflows/factory/backlog/scripts/publish.ts', 'import { emit, env, ghJson, readJsonFile, run } from "../../.shared/utils.ts";

const repo = env("repo_path"), tickets = readJsonFile<any[]>(`${process.env.ARTIFACTS_DIR}/backlog.json`);
const listed = ghJson(["issue", "list", "--repo", repo, "--state", "all", "--limit", "1000", "--json", "number,url,body"]) as any[];
const created: string[] = [], existing: string[] = [], numbers = new Map<string, number>();
for (const ticket of tickets) {
  const marker = `<!-- factory-backlog: ${ticket.key} -->`;
  const prior = listed.find(issue => issue.body?.includes(marker));
  if (prior) { existing.push(prior.url); numbers.set(ticket.key, prior.number); continue; }
  const dependencies = ticket.depends_on.map((key: string) => `Depends on: #${numbers.get(key)}`).join("\n");
  const body = ticket.body.replace(marker, "").trim() + (dependencies ? `\n\n${dependencies}` : "") + `\n\n${marker}\n`;
  const file = `${process.env.ARTIFACTS_DIR}/issue-${ticket.key}.md`; await Bun.write(file, body);
  const url = run(["gh", "issue", "create", "--repo", repo, "--title", ticket.title, "--body-file", file]);
  const number = Number(url.match(/\/(\d+)$/)?.[1]);
  if (!number) throw new Error(`could not read created issue URL: ${url}`);
  created.push(url); numbers.set(ticket.key, number); listed.push({ url, number, body });
}
emit({ published: true, created, existing });
');
INSERT INTO mc.arch_scripts (archon_sha, factory_sha, path, text) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '.archon/workflows/factory/backlog/scripts/read.ts', 'import { existsSync, readFileSync } from "node:fs";
import { isAbsolute, relative, resolve } from "node:path";
import { emit, env, ghJson } from "../../.shared/utils.ts";

const repo = env("repo_path"), number = env("number"), named = env("prd_path");
if (Boolean(number) === Boolean(named)) throw new Error("provide exactly one of number or prd_path");
let source: string, text: string;
if (number) { const issue = ghJson(["issue", "view", number, "--repo", repo, "--json", "body,url"]); source = issue.url; text = issue.body; }
else {
  const root = resolve("."), path = resolve(named);
  if (isAbsolute(named) && !path.startsWith(root) || relative(root, path).startsWith("..") || !existsSync(path)) throw new Error("prd_path must be a file inside the checkout");
  source = relative(root, path); text = readFileSync(path, "utf8");
}
if (text.trim().length < 200) throw new Error("PRD is too short (minimum 200 characters)");
const path = `${process.env.ARTIFACTS_DIR}/backlog-prd.md`;
await Bun.write(path, text);
emit({ source, path, characters: text.length });
');
INSERT INTO mc.arch_scripts (archon_sha, factory_sha, path, text) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '.archon/workflows/factory/deploy/scripts/preflight.ts', 'import { existsSync } from "node:fs";
import { resolve } from "node:path";

const revision = process.env.INPUTS_REVISION?.trim() ?? "";
if (!/^[0-9a-f]{40}$/i.test(revision)) throw new Error("revision must be an exact 40-character commit id");
const deployDoc = resolve("DEPLOY.md");
if (!existsSync(deployDoc)) throw new Error("DEPLOY.md is required; factory-deploy never invents deployment instructions");
console.log(JSON.stringify({ revision: revision.toLowerCase(), deploy_doc: deployDoc, started_at: Date.now() }));
');
INSERT INTO mc.arch_scripts (archon_sha, factory_sha, path, text) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '.archon/workflows/factory/deploy/scripts/verify.ts', 'import { existsSync, mkdirSync, statSync, writeFileSync } from "node:fs";
import { basename, join } from "node:path";
import { env, jsonEnv } from "../../.shared/utils.ts";

export function verifyDeployment(requested: string, reported: string, deployed: string, health: string, evidence: string[], startedAt: number) {
  requested = requested.toLowerCase(); reported = reported.toLowerCase(); deployed = deployed.toLowerCase();
  if (!requested || reported !== requested) throw new Error("deployment report did not bind to the requested revision");
  if (deployed !== requested) throw new Error(`deployed revision mismatch: requested ${requested}, observed ${deployed || "nothing"}`);
  if (health !== "healthy") throw new Error(`deployment health check was ${health || "not reported"}`);
  if (!evidence.length) throw new Error("deployment returned no evidence files");
  if (!evidence.some(file => basename(file).toLowerCase() === "report.md")) throw new Error("deployment evidence must include report.md");
  for (const file of evidence) {
    if (!existsSync(file) || !statSync(file).isFile()) throw new Error(`deployment evidence is missing: ${file}`);
    if (!Number.isFinite(startedAt) || statSync(file).mtimeMs < startedAt) throw new Error(`deployment evidence is stale: ${file}`);
  }
  return { deployed: true, revision: deployed, health, evidence_files: evidence };
}

/** A failed deployment has no open pull request to return to, so it is recorded for the discoveries workflow to file as new work. */
export function recordFailedDeployment(artifacts: string, requested: string, reason: string, evidence: string[]): void {
  const dir = join(artifacts, "discoveries");
  mkdirSync(dir, { recursive: true });
  writeFileSync(join(dir, "deploy.json"), JSON.stringify([{
    title: `Deploying ${requested.slice(0, 7) || "the requested revision"} failed`,
    claim: reason,
    evidence: [`requested revision: ${requested || "none"}`, ...evidence],
    relation: "unrelated",
    source_node: "deploy",
  }], null, 2));
}

if (import.meta.main) {
  const evidence = jsonEnv<string[]>("evidence_files", []);
  try {
    console.log(JSON.stringify(verifyDeployment(
      env("requested_revision"), env("reported_requested_revision"), env("deployed_revision"), env("health_status"),
      evidence, Number(env("started_at")),
    )));
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    if (process.env.ARTIFACTS_DIR) recordFailedDeployment(process.env.ARTIFACTS_DIR, env("requested_revision"), reason, evidence);
    throw error;
  }
}
');
INSERT INTO mc.arch_scripts (archon_sha, factory_sha, path, text) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '.archon/workflows/factory/setup/scripts/apply.ts', 'import { applyFactoryConfig } from "../../../../scripts/factory-config.ts";
console.log(JSON.stringify(applyFactoryConfig()));
');
INSERT INTO mc.arch_hooks (archon_sha, factory_sha, path, text, admitted_agents) VALUES ('57c8574020000000000000000000000000000000', '6311108f789119a8a1a6a7c77ece21ca3a75c3e8', '.factory/hooks/holdout_fence.py', '"""The holdout fence: only the holdout subagents may see .factory/holdout/, and nothing may change the fence.

Claude Code runs this before every tool call (`pre`) and tags each call a subagent makes with its
`agent_type`. Calls from `holdout-writer` and `holdout-verifier` pass. Every other call (builders,
reviewers, the manager itself, a human session) is refused, by exit 2, when it would show a scenario:

- it names the folder or a HOLDOUT.md, or globs into `.factory`;
- it is a recursive search whose scope covers the folder. The Grep and Glob tools skip the folder
  through `.ignore`; shell `grep -r`, `git grep` and `rg --no-ignore` do not;
- it is a `git diff`, `git log -p` or `git show` whose output would include a file in the folder.
  Git is asked with `--name-only`, so a command that cannot reach the folder is never refused.

Any call that would change the fence itself (this folder, `.claude/settings.json`, `.ignore`) is
refused for everyone. After each call (`post`) the result is checked for scenario text, and a hit is
appended to `holdout-exposures.jsonl` in the repository''s git directory, so a leak the fence did not
foresee is counted instead of invisible.

Claude Code lets a call through when a hook errors, so `pre` fails closed: an error is a refusal.
"""

import json
import os
import re
import shlex
import subprocess
import sys
import time
from pathlib import Path

HOLDOUT_AGENTS = {"holdout-writer", "holdout-verifier"}
FOLDER = ".factory/holdout"
# Tools that read, search or change files, or hand work to another agent. Output-only tools
# (StructuredOutput, TodoWrite, ...) are never refused for mentioning the folder.
ACCESS_TOOLS = {"Bash", "PowerShell", "Read", "Grep", "Glob", "Edit", "Write", "MultiEdit",
                "NotebookEdit", "NotebookRead", "Agent", "Task"}
WRITE_TOOLS = {"Edit", "Write", "MultiEdit", "NotebookEdit"}
SHELL_TOOLS = {"Bash", "PowerShell"}

NAMED = re.compile(r"\.factory/+(?:holdout(?![\w-])|[*?\[])|(?<![\w-])holdout\.md\b", re.I)
FENCE = re.compile(r"\.factory/+hooks(?![\w-])|\.claude/+settings(?:\.local)?\.json|(?<![\w.])\.ignore\b", re.I)
MUTATES = re.compile(
    r">|\btee\b|\b(?:sed|perl)\s+-\w*i|\b(?:rm|mv|cp|chmod|truncate|ln|install)\b|"
    r"\bgit\s+(?:checkout|restore|rm|mv|reset|stash)\b|Set-Content|Add-Content|Out-File|"
    r"Remove-Item|Move-Item|Copy-Item|Rename-Item", re.I)
SEGMENT = re.compile(r"\s*(?:&&|\|\||;|\||\n)\s*")
NO_PATCH = {"--stat", "--name-only", "--name-status", "--numstat", "--shortstat", "--summary",
            "-s", "--no-patch", "--quiet", "--exit-code", "--raw"}
LOG_PATCH = re.compile(r"^(?:-p|--patch|-u|-U\d*|--unified(?:=\d+)?|--full-diff|-m|--cc|-c)$")
PROBE_DROP = re.compile(r"^(?:-p|--patch|-u|-U\d*|--unified(?:=\d+)?|--stat(?:=.*)?|--color(?:=.*)?|"
                        r"--format(?:=.*)?|--pretty(?:=.*)?|--oneline|--graph|-w|--word-diff(?:=.*)?)$")
GREP_ARG_OPTS = {"-e", "-f", "-A", "-B", "-C", "-m", "-d", "-D", "--context", "--max-count", "--include",
                 "--exclude", "--exclude-dir", "--regexp", "--file"}


def refuse(reason: str) -> None:
    print(f"Blocked by the holdout fence: {reason}. The holdout scenarios are for the "
          "holdout-verifier and holdout-writer subagents only; scope searches and diffs to source "
          "folders (or exclude .factory).", file=sys.stderr)
    sys.exit(2)


def normal(path: str) -> str:
    """A comparable absolute path: forward slashes, Git Bash drive form folded, case folded on Windows."""
    path = path.strip().strip("''\"").replace("\\", "/")
    drive = re.match(r"^/([a-zA-Z])(/|$)", path)
    if drive and os.name == "nt":
        path = f"{drive.group(1)}:/{path[3:]}"
    path = os.path.normpath(os.path.expanduser(path)).replace("\\", "/")
    return path.lower() if os.name == "nt" else path


def resolve(path: str, cwd: str) -> str:
    path = path.strip().strip("''\"")
    static = re.split(r"[*?\[{]", path, maxsplit=1)[0]
    if static != path:
        static = static.rsplit("/", 1)[0] if "/" in static else ""
    raw = static.replace("\\", "/")
    if raw == "" or not (raw.startswith("/") or re.match(r"^[a-zA-Z]:", raw) or raw.startswith("~")):
        raw = os.path.join(cwd, raw) if raw else cwd
    return normal(raw)


def covers(path: str, holdout: str) -> bool:
    path = path.rstrip("/")
    return holdout == path or holdout.startswith(path + "/")


def tokens(segment: str, posix: bool = True) -> list[str]:
    try:
        words = [w.strip("''\"") for w in shlex.split(segment, posix=posix)]
    except ValueError:
        words = segment.split()
    while words and re.match(r"^\w+=", words[0]):
        words = words[1:]
    return words


def excluded(words: list[str]) -> bool:
    """The search excludes .factory (or the holdout folder) itself."""
    text = " ".join(words).replace("\\", "/")
    return bool(re.search(r"(--exclude-dir[= ]\S*(\.factory|holdout|\.\*))|(:\(exclude\)|:!|:\^)\S*\.factory"
                          r"|(-g|--glob)[= ][''\"]?!\S*\.factory", text, re.I))


def grep_paths(args: list[str]) -> tuple[bool, list[str]]:
    recursive, positional, has_pattern_opt, skip = False, [], False, False
    for index, arg in enumerate(args):
        if skip:
            skip = False
            continue
        if arg == "--":
            positional.extend(args[index + 1:])
            break
        if arg.startswith("--"):
            recursive |= arg in ("--recursive", "--dereference-recursive")
            has_pattern_opt |= arg.startswith(("--regexp", "--file"))
            skip = arg in GREP_ARG_OPTS
        elif arg.startswith("-") and len(arg) > 1:
            letters = arg[1:]
            recursive |= "r" in letters or "R" in letters
            has_pattern_opt |= "e" in letters or "f" in letters
            skip = arg in GREP_ARG_OPTS or letters[-1:] in ("e", "f", "A", "B", "C", "m")
        else:
            positional.append(arg)
    paths = positional if has_pattern_opt else positional[1:]
    return recursive, paths


def git_probe(words: list[str], cwd: str, holdout_rel: str) -> bool:
    """Whether a git diff/log/show would print a file under the holdout folder."""
    index, base = 1, cwd
    while index < len(words) and words[index].startswith("-"):
        if words[index] in ("-C", "-c") and index + 1 < len(words):
            base = resolve(words[index + 1], cwd) if words[index] == "-C" else base
            index += 2
        else:
            index += 1
    if index >= len(words) or words[index] not in ("diff", "log", "show", "whatchanged"):
        return False
    sub, rest = words[index], words[index + 1:]
    if any(arg in NO_PATCH for arg in rest) and not any(LOG_PATCH.match(arg) for arg in rest):
        return False
    if sub in ("log", "whatchanged") and not any(LOG_PATCH.match(arg) for arg in rest):
        return False
    probe = ["git", "-C", base, sub, "--name-only"] + (["--format="] if sub != "diff" else [])
    probe += [arg for arg in rest if not PROBE_DROP.match(arg)]
    try:
        out = subprocess.run(probe, capture_output=True, text=True, timeout=20).stdout
    except (OSError, subprocess.SubprocessError):
        return False
    return any(line.strip().replace("\\", "/").startswith(holdout_rel + "/") for line in out.splitlines())


def check_shell(command: str, cwd: str, holdout: str, posix: bool) -> None:
    for segment in SEGMENT.split(command):
        words = tokens(segment, posix)
        if not words:
            continue
        program = words[0].rsplit("/", 1)[-1].lower()
        if program == "cd" and len(words) > 1:
            cwd = resolve(words[1], cwd)
            continue
        if program in ("grep", "egrep", "fgrep"):
            recursive, paths = grep_paths(words[1:])
            if recursive and not excluded(words) and any(covers(resolve(p, cwd), holdout) for p in paths or ["."]):
                refuse(f"`{segment.strip()[:80]}` searches the folder")
        elif program == "rg":
            no_ignore = any(re.match(r"^(-u+|--no-ignore(-dot|-files|-vcs)?)$", w) for w in words[1:])
            if no_ignore and not excluded(words):
                paths = [w for w in words[1:] if not w.startswith("-")][1:]
                if any(covers(resolve(p, cwd), holdout) for p in paths or ["."]):
                    refuse(f"`{segment.strip()[:80]}` searches the folder without .ignore")
        elif program == "git" and "grep" in words[1:3]:
            rest = words[words.index("grep") + 1:]
            specs = rest[rest.index("--") + 1:] if "--" in rest else []
            if not excluded(words) and any(covers(resolve(p, cwd), holdout) for p in specs or ["."]):
                refuse(f"`{segment.strip()[:80]}` searches the folder")
        elif program == "git" and git_probe(words, cwd, FOLDER):
            refuse(f"`{segment.strip()[:80]}` would print a holdout file")


def pre(event: dict) -> None:
    tool = event.get("tool_name", "")
    tool_input = event.get("tool_input") or {}
    text = json.dumps(tool_input).replace("\\\\", "/")
    holdout_agent = event.get("agent_type") in HOLDOUT_AGENTS
    target = json.dumps([tool_input.get(key, "") for key in ("file_path", "notebook_path")]).replace("\\\\", "/")
    if tool in WRITE_TOOLS and FENCE.search(target):
        refuse("the fence itself only changes by hand")
    if tool in SHELL_TOOLS and FENCE.search(text) and MUTATES.search(tool_input.get("command", "")):
        refuse("the fence itself only changes by hand")
    if holdout_agent or tool not in ACCESS_TOOLS:
        return
    if tool in ("Agent", "Task") and tool_input.get("subagent_type") in HOLDOUT_AGENTS:
        return
    if NAMED.search(text):
        refuse("the call names the holdout folder")
    if tool in SHELL_TOOLS:
        root = normal(os.environ.get("CLAUDE_PROJECT_DIR") or event.get("cwd") or os.getcwd())
        cwd = normal(event.get("cwd") or root)
        check_shell(tool_input.get("command", ""), cwd, f"{root}/{FOLDER}", tool == "Bash")


def strings(value) -> list[str]:
    if isinstance(value, str):
        return [value]
    if isinstance(value, dict):
        return [s for item in value.values() for s in strings(item)]
    if isinstance(value, list):
        return [s for item in value for s in strings(item)]
    return []


def squash(text: str) -> str:
    return " ".join(text.lower().split())


def post(event: dict) -> None:
    if event.get("agent_type") in HOLDOUT_AGENTS:
        return
    root = Path(os.environ.get("CLAUDE_PROJECT_DIR") or event.get("cwd") or os.getcwd())
    scenarios = root / FOLDER / "HOLDOUT.md"
    if not scenarios.is_file():
        return
    current, prints = "", {}
    for line in scenarios.read_text(encoding="utf-8", errors="replace").splitlines():
        heading = re.match(r"^#{2,3}\s+(\S+)", line)
        if heading:
            current = heading.group(1)
        flat = squash(line.lstrip("#"))
        if len(flat) >= 40:
            prints[flat] = current
    seen = squash("\n".join(strings(event.get("tool_response"))))
    hits = sorted({scenario for flat, scenario in prints.items() if flat in seen})
    if not hits:
        return
    common = subprocess.run(["git", "rev-parse", "--git-common-dir"], cwd=root, capture_output=True,
                            text=True, timeout=20).stdout.strip()
    log = (root / common if common else root / ".git") / "holdout-exposures.jsonl"
    with open(log, "a", encoding="utf-8") as handle:
        handle.write(json.dumps({"at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                                 "session": event.get("session_id", ""), "agent": event.get("agent_type", ""),
                                 "tool": event.get("tool_name", ""), "scenarios": hits}) + "\n")


def main() -> None:
    mode = sys.argv[1] if len(sys.argv) > 1 else "pre"
    try:
        event = json.load(sys.stdin)
        (post if mode == "post" else pre)(event)
    except SystemExit:
        raise
    except Exception as error:  # noqa: BLE001 - any failure must refuse, never let the call through
        if mode == "post":
            sys.exit(0)
        refuse(f"the fence could not check this call ({type(error).__name__}: {error})")
    sys.exit(0)


if __name__ == "__main__":
    main()
', ARRAY['holdout-writer', 'holdout-verifier']::text[]);

